export default [{"id":85,"question":"رُوي عن ابن مسعودٍ  أنه قال: \"إنَّا كنا في حياة النبي ﷺ نقول في التَّشهد: السلام عليك أيُّها النبي ورحمةُ الله وبركاته، وبعد وفاته كنا نقول: السلام على النبي ورحمة الله وبركاته\"، فهل هذا صحيحٌ؟ وهل نقوله في التَّشهد؟","title":"ما صيغة السلام على النبي ﷺ في التشهد؟","answer":"الجواب: المشروع أن نقول مثلما علَّم النبيُّ ﷺ أصحابَه، فقد علَّمهم أن يقولوا: السلام عليك أيُّها النبيُّ ورحمة الله وبركاته، فنقول كما علَّم الرسولُ ﷺ الصحابة، ولم يقل لهم: إذا متُّ فغيِّروا، علَّمهم وهم مسافرون إلى البلاد البعيدة أن يقولوا: السلام عليك أيُّها النبي ورحمة الله، يعني: يدعون له، فـالسلام عليك هي دعاء له بالسلامة والرحمة والبركة، وأيها النبي معناها: استحضار النبي، وليس معناها أنهم يدعونه، وقولهم السلام عليك يعني: لك السلامة، ولك العافية والرحمة والبركة من ربك، وهو دعاء للنبيِّ ﷺ، وليس يُدْعَى هو، ولكنك تطلب من الله له السلامة والرحمة والبركة.\nومَن قال: \"السلام على النبي ورحمة الله وبركاته\" فلا بأس، لكن الأفضل أن يقول كما علَّم النبيُّ ﷺ الصحابة: السلام عليك أيها النبي ورحمة الله وبركاته، هذا هو الذي علَّمه النبيُّ أمته، ومات على ذلك عليه الصلاة والسَّلام.","link":"https://binbaz.org.sa/fatwas/3083/ما-صيغة-السلام-على-النبي-ﷺ-في-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0062.mp3","categories":["التشهد والتسليم"]},{"id":169,"question":"إذا صلَّى المُصلي صلاة المغرب ونسي التَّشهد الأخير فما حكمه؟","title":"حكم من نسي التشهد الآخير في الصلاة","answer":"الجواب: صلاة المغرب أو غيرها: إذا نسي التَّشهد الأخير من صلاة المغرب أو غيرها من الصَّلوات يعود إلى مجلسه ويأتي بالتَّشهد الأخير، ثم يسجد للسهو ويُسلِّم، أو يُسلِّم ثم يسجد للسهو، فإن شاء سجد للسهو قبل ذلك أو بعد ذلك، والأفضل بعد السَّلام؛ لأنه سلَّم عن نقصٍ، فإذا نسي التشهد الأخير وسلَّم يعود إلى الصلاة إذا كان الفصلُ ليس بطويلٍ، ما طال الفصل، ولو قام من مكانه، ولو خرج يرجع فيجلس ويأتي بالتشهد ثم يُسلِّم ثم يسجد للسهو، هذا هو الأفضل، وإن سجد قبل السلام فلا بأس.\nوالدليل على هذا أنَّ النبي ﷺ في بعض الصَّلوات سلَّم من ثلاثٍ وخرج، فأشار له الناسُ أنه بقيت عليه ركعةٌ، فرجع وأتمَّ الركعة وسلَّم وسجد للسهو عليه الصلاة والسلام.\nوفي حديث ذي اليدين -حديث أبي هريرة- أنه صلَّى الظهر أو العصر ركعتين وقام من مكانه إلى مكانٍ آخر، فنُبِّهَ أنه سلَّم من ثنتين، فعاد فكمَّل الصلاة وسلَّم ثم سجد للسهو، مع أنه قد قام من مكانه واستقبل غير جهة القبلة يحسب أنه أتمَّ صلاته، والنبي ﷺ ينسى كما ينسى غيرُه، يقول ﷺ: إنما أنا بشرٌ أنسى كما تنسون، فإذا نسيتُ فذكِّروني، هكذا قال عليه الصلاة والسلام.\nأما إذا طال الفصلُ يُعيد الصلاة من أولها، إذا طال الفصلُ عُرفًا؛ فإنه يُعيد الصلاة من أولها.","link":"https://binbaz.org.sa/fatwas/3707/حكم-من-نسي-التشهد-الاخير-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0164.mp3","categories":["التشهد والتسليم","سجود السهو"]},{"id":1035,"question":"ما حكم التَّسليمة الثانية: أهي واجبة أم سنة؟","title":"هل التَّسليمة الثانية بالصلاة واجبة أم سُنة؟","answer":"الجواب: الصحيح أنها واجبة؛ لأن الرسول ﷺ كان يُسلِّم عن يمينه وشماله، وهكذا جاءت الأحاديث الصَّحيحة، ويقول: صلُّوا كما رأيتُموني أُصلِّي. وذهب الأكثرون إلى أنها سنة، ولكن الأرجح قول مَن قال بأن التَّسليمتين فرضٌ وركنٌ؛ لأن الرسول حافظ عليهما، وقال: صلُّوا كما رأيتُموني أُصلِّي.","link":"https://binbaz.org.sa/fatwas/21090/هل-التسليمة-الثانية-بالصلاة-واجبة-ام-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0886ما حكم التسليمة الثانية هل هي واجبة أم سنة؟ ابن باز فتاوى المحاضرات.mp3","categories":["التشهد والتسليم"]},{"id":2246,"question":"رجل يسأل عن حكم صلاته، يقول: صليتُ عند الصلاة على النبي ﷺ فقلتُ: اللهم صلِّ على محمدٍ، ثم سلَّمتُ، يعني أنَّه ما صلَّى على النبي الصلاة الكاملة؟","title":"حكم الصلاة على النبي في التشهد بغير الوارد","answer":"الجواب:\nالصلاة صحيحة، لكن ترك ما ينبغي؛ لأنَّ النبي ﷺ لما سألوه قال: قولوا: اللَّهم صلِّ ..، ولم يأتِ ما يدل على الإلزام بها، لكن من باب الاحتياط يُؤتَى بها في التَّشهد الأخير ويتأكّد ذلك؛ خروجًا من الخلاف.\nس: إذن الفرض أن يقول: \"اللهم صلِّ على محمدٍ\" فقط؟\nج: ينبغي أن يأتي بها على حالها وعلى صفتها: \"اللهم صلِّ على محمدٍ، وعلى آل محمدٍ، كما صليتَ على آل إبراهيم، وبارك على محمدٍ، وعلى آل محمدٍ، كما باركتَ على آل إبراهيم\"، وإن جمع بين الآلَين فهو أفضل: محمد وآله، وإبراهيم وآله.\nس: هل هي واجبة أو ركن؟\nج: جملة من العلماء يرون أنها ركن، وجملة آخرون يرون أنها واجب، وطائفة ثالثة ترى أنها سُنة، ولكن على كلِّ حال لا ينبغي تركها؛ خروجًا من الخلاف، في التَّشهد الأخير.","link":"https://binbaz.org.sa/fatwas/22369/حكم-الصلاة-على-النبي-في-التشهد-بغير-الوارد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة على النبي في التشهد.mp3","categories":["التشهد والتسليم"]},{"id":2306,"question":"ما صفة الإشارة بالسّبابة: مع لفظ الجلالة والدّعاء أم مع الدعاء فقط؟","title":"ما صفة الإشارة بالسّبابة في التشهد؟","answer":"الجواب:\nمن حين أن يجلس للتَّشهد يُشير هكذا، وعند الدّعاء يُحرِّكها قليلًا.\nس: أمَّا مع لفظ الجلالة فلا يُحرّكها؟\nج: يرفع أُصبعه حتى يُسلِّم، يُشير بالسبابة للوحدانية.","link":"https://binbaz.org.sa/fatwas/22430/ما-صفة-الاشارة-بالسبابة-في-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صفة الإشارة بالسّبابة في التشهد.mp3","categories":["التشهد والتسليم"]},{"id":2432,"question":"زيادة \"وبركاته\" بعد السلام بعد الفراغ من الصلاة؟","title":"حكم زيادة \"وبركاته\" في السلام مِن الصلاة","answer":"الجواب:\nجاء في بعض الروايات، لكن أصح منها: ورحمة الله الذي عليه العمل الآن عن الشذوذ والاختلاف..... جاءت في بعض الروايات زيادة \"وبركاته\" لكن تَرْكُها أوْلى، العمل بالشيء الذي عليه عمل المسلمين الآن هو أوْلى (السلام عليكم ورحمة الله) كما في حديث جابر بن سمرة: كان النبي ﷺ إذا سلم قال: السلام عليكم ورحمة الله، السلام عليكم ورحمة الله.\nس: الزيادة صحيحة؟\nالشيخ: صححها جماعة من أهل العلم، وبعضهم قال شاذة زائدة، ولكن تركها أوْلى؛ لأن العمل على خلافها؛ خروجًا من الخلاف.","link":"https://binbaz.org.sa/fatwas/22560/حكم-زيادة-وبركاته-في-السلام-من-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/زيادة وبركاته في السلام في الصلاة.mp3","categories":["التشهد والتسليم"]},{"id":2834,"question":"زيادة \"وبركاته\" في التسليم في الصلاة صحيحة؟","title":"هل زيادة \"وبركاته\" في التسليم من الصلاة صحيحة؟","answer":"الجواب: جاءت في هذا أحاديث، ذكر الحافظ في البلوغ أنها صحيحة، لكن جماعة آخرون قالوا أنها شاذة، فالأَوْلى الاقتصار على (ورحمة الله) على ما عليه العمل الآن؛ لأن هذا هو الثابت في صحيح مسلم من حديث سَمُرَة: كانوا إذا سلموا يقولون: السلام عليكم ورحمة الله، في الصلاة.","link":"https://binbaz.org.sa/fatwas/22983/هل-زيادة-وبركاته-في-التسليم-من-الصلاة-صحيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم زيادة وبركاته في التسليم في الصلاة.mp3","categories":["التشهد والتسليم"]},{"id":2869,"question":"الواجب في التشهد الأخير: هل الصفات الواردة، أم يقول: \"اللهم صل على محمد\" هو الكافي؟","title":"ماذا يجب في الصلاة على النبي في التشهد؟","answer":"الجواب: الأولى أن يأتي بصفة من الصفات أحْوَط، واحدة من الصفات، وإلا عند العلماء: يكفي اللهم صل على محمد.","link":"https://binbaz.org.sa/fatwas/23024/ماذا-يجب-في-الصلاة-على-النبي-في-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الواجب في الصلاة على النبي في التشهد.mp3","categories":["التشهد والتسليم"]},{"id":2885,"question":"موافقة الإمام في التسليم؟","title":"حكم موافقة الإمام في التسليم","answer":"الجواب: لا ما ينبغي، بعده، كان الصحابة إذا سلّم النبي ﷺ سلّموا.","link":"https://binbaz.org.sa/fatwas/23040/حكم-موافقة-الامام-في-التسليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم موافقة الإمام في التسليم.mp3","categories":["التشهد والتسليم"]},{"id":3220,"question":"زيادة (وبركاته) في السلام بعد الفراغ مِن الصلاة؟","title":"حكم زيادة \"وبركاته\" في السلام من الصلاة","answer":"الجواب: جاءت في بعض الروايات، في بعضها ضعف، والأقرب الاقتصار على \"رحمة الله\" كما روى سمرة قال: كان النبي ﷺ يقول: السلام عليكم ورحمة الله، السلام عليكم ورحمة الله.\nس: \"بركاته\" هذه ضعيفة؟\nالشيخ: نعم شاذة، السلام من الصلاة أن يقول: \"السلام عليكم ورحمة الله\" حين يُسَلّم من الصلاة.  أما مع الناس فهي أكملُ، السلام على الناس.","link":"https://binbaz.org.sa/fatwas/23383/حكم-زيادة-وبركاته-في-السلام-من-الصلاة","audio":"undefined","categories":["التشهد والتسليم"]},{"id":3598,"question":"التعوذ بالله من الأربع هذه واجب أم سنة؟","title":"هل التعوذ من أربع في التشهد واجب أم سنة؟","answer":"الجواب: عند الجمهور سنة، ويروى عن طاوس أنه كان يأمر ابنه بالإعادة إذا تركها لأن الرسول ﷺ أمر بها: إذا تشهد أحدكم فليستعذ بالله من أربع فينبغي للمؤمن ألا يدعها وإن كان الجمهور يرونها سنة، لكن ينبغي له ألا يدعها؛ لأن الرسول أمر بها عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/23780/هل-التعوذ-من-اربع-في-التشهد-واجب-ام-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث إذا تشهد أحدكم فليستعذ بالله من أربع... التعوذ واجب أم سنة.mp3","categories":["التشهد والتسليم","شروح الحديث"]},{"id":3599,"question":"قول عائشة \"أيها النبي\" إنما كان في حال حياته ﷺ؟","title":"ما الصواب في صيغة السلام في التشهد؟","answer":"الجواب: الصواب أنه مثل ما علم النبي ﷺ أصحابه: السلام عليك أيها النبي هو علّم أصحابه وهو يعلم أنه يموت ويعلم أنهم يغيبون.","link":"https://binbaz.org.sa/fatwas/23781/ما-الصواب-في-صيغة-السلام-في-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السلام على النبي في التشهد.mp3","categories":["التشهد والتسليم"]},{"id":3600,"question":"بعض العامة إذا انتهى من التشهد الأول والإمام ما زال جالسًا يعيد مرة أخرى، فقيل له: ادع، فقال: أحب أن أعيد مرة ثانية وثالثة؟","title":"ما يفعل المأموم لو أطال الإمام التشهد؟","answer":"الجواب: لا، يصلي على النبي ﷺ بعد التشهد الأول، ولو عاد ما يضر.\nس: إذا كان الإمام أسرع في التشهد ولم يدركه؟\nالشيخ: يكمل التشهد.","link":"https://binbaz.org.sa/fatwas/23782/ما-يفعل-الماموم-لو-اطال-الامام-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إعادة التشهد في الصلاة.mp3","categories":["التشهد والتسليم"]},{"id":3601,"question":"الدعاء الذي يقول \"وأنا أول المسلمين\" يقوله كذلك، أو يقول: \"وأنا من المسلمين\"؟","title":"هل يصح الدعاء بقول: \"وأنا أول المسلمين\"؟","answer":"الجواب: وأنا من المسلمين. هو ما هو بأول المسلمين، النبيﷺ أول المسلمين.","link":"https://binbaz.org.sa/fatwas/23783/هل-يصح-الدعاء-بقول-وانا-اول-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقال وأنا أول المسلمين، أو وأنا من المسلمين في التشهد.mp3","categories":["التشهد والتسليم"]},{"id":4022,"question":"قول ابن مسعود: فلما قبض قلنا السلام على النبي؟","title":"هل يصح قول \"السلام على النبي\"؟","answer":"الجواب: هذا من اجتهاده، النبي علّمهم ولم يقل لهم هذا، علمهم أن يقولوا: السلام عليك أيها النبي، هذا تعليم منه ﷺ، فالسنة أن يقول: السلام عليك أيها النبي، كما علمهم النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/24258/هل-يصح-قول-السلام-على-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول ابن مسعود فلما قبض قلنا السلام على النبي.mp3","categories":["التشهد والتسليم"]},{"id":4057,"question":"في العالمين...؟","title":"حكم زيادة \"في العالمين\" في التشهد","answer":"الجواب: جاء في رواية أيضًا: في العالمين، رواه مسلم في الصحيح.","link":"https://binbaz.org.sa/fatwas/24294/حكم-زيادة-في-العالمين-في-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/زيادة في العالمين في الصلاة على النبي في التشهد.mp3","categories":["التشهد والتسليم"]},{"id":4450,"question":"يُحرِّك السبابة عند الشَّهادة؟","title":"ما كيفية رفع السبّابة وتحريكها في التشهد؟","answer":"الجواب: لا، لم أقف عليه في شيء من الروايات، ما أذكر أني وقفتُ على رفع السبابة، لكن جاء في رواية ابن عباس عند أبي داود بسندٍ جيدٍ، وهو يدل عند ذكر التوحيد عند الشهادة يُشير بالأصبع، قد يعمّ هذا.\nس: تحريك السّبابة عند الشَّهادة؟\nج: تقدم في الحديث الضَّعيف.\nس: في كل وقتٍ أو خاصّ؟\nج: الذي يظهر عند الدّعاء، وعند... التوحيد، وعند الدعاء إشارة للتوحيد، أما السبابة فتكون واقفة، تكون واقفة منحنية قليلًا، كما في رواية النسائي، لكن ... في التوحيد أو الدعاء يُحركها قليلًا جمعًا بين الروايات.","link":"https://binbaz.org.sa/fatwas/24728/ما-كيفية-رفع-السبابة-وتحريكها-في-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رفع السبّابة عن الشهادة.mp3","categories":["التشهد والتسليم"]},{"id":4571,"question":"الإقعاء المشروع عفا الله عنك؟","title":"ما صفة الإقعاء المشروع في الصلاة؟","answer":"الجواب: الإقعاء الذي ورد عن ابن عباس أنه من السنة؛ فذاك جلوسه على عقبيه مفروشتين أو منصوبتين، على العقبين منصوبتان –القدمان- أو مفروشتان، ويجلس على عقبيه، هذا جاء عن ابن عباس، لكن المعروف في الأحاديث الصحيحة الافتراش، أحاديث الافتراش أكثر، ورواية ابن عباس في مسلم ذكر أنها من السنة، ولعلَّ النبيَّ فعلها بعض الأحيان عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24854/ما-صفة-الاقعاء-المشروع-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صفة الإقعاء المشروع.mp3","categories":["التشهد والتسليم"]},{"id":4572,"question":"قول ابن مسعودٍ  يقول: حينما كنا على عهد النبي ﷺ كنا نقول: \"السلام عليك أيها النبي\"، وحينما توفي كنا نقول: \"السلام على النبي\"؟","title":"حكم\"السلام عليك أيها النبي\" بعد موتهﷺ","answer":"الجواب: لا، هذا من اجتهاد ابن مسعود، والنبي علَّمهم ولم يقل لهم هذا، النبي علَّمهم أنهم يقولون: السلام عليك أيها النبي، وهو يعلم أنه يموت عليه الصلاة والسلام، وهم يقولونه وهم غائبون؛ الذين في العراق، والذين في الشام، والذين في اليمن يقولون هذا وهم غائبون عنه، وهم في مكة وغيرها، فالأفضل أن يقول كما علَّم النبيُّ ﷺ: السلام عليك أيها النبي، هكذا، وإذا قال: \"السلام على النبي\" كما قال ابنُ مسعودٍ فلا بأس، لكن السنة الألفاظ التي علَّمها النبيُّ أصحابه أولى، أولى من اجتهاد ابن مسعودٍ.","link":"https://binbaz.org.sa/fatwas/24855/حكم-السلام-عليك-ايها-النبي-بعد-موتهﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول ابن مسعودٍ كنا نقول السلام عليك أيها النبي، وحينما توفي كنا نقول السلام على النبي.mp3","categories":["التشهد والتسليم"]},{"id":4573,"question":"في العالمين إنك حميد مجيد...؟","title":"حكم زيادة \"في العالمين\" في التشهد","answer":"الجواب: هذه في الصلاة على النبي ﷺ، هذه ما هي في التشهد، في الصلاة على النبي ﷺ، إذا قال: \"في العالمين\" لا بأس، جاء في رواية أبي مسعود: \"اللهم صلِّ على محمدٍ وعلى آل محمدٍ كما صليتَ على آل إبراهيم، وبارك على محمدٍ وعلى آل محمدٍ كما باركتَ على آل إبراهيم في العالمين ..\".","link":"https://binbaz.org.sa/fatwas/24856/حكم-زيادة-في-العالمين-في-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/زيادة في العالمين إنك حميد مجيد في التشهد.mp3","categories":["شروح الحديث","التشهد والتسليم"]},{"id":4575,"question":"إذا كانت السبابة مقطوعةً، إذا كان الأصبع هنا أصبعًا مقطوعًا..؟","title":"حكم الإشارة في التشهد لمن سبابته مقطوعة","answer":"الجواب: الظاهر -والله أعلم- أنه إذا أشار بالوسطى أو بالإبهام فكله خير إن شاء الله، المقصود الإشارة إلى التوحيد، فإذا أشار بما بقي منها كفى، إذا كان بقي منها شيء وأشار بالباقي كفى.","link":"https://binbaz.org.sa/fatwas/24858/حكم-الاشارة-في-التشهد-لمن-سبابته-مقطوعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإشارة بالسبابة عند التشهد، فإن كانت مقطوعة.mp3","categories":["التشهد والتسليم"]},{"id":4577,"question":"الالتفاف عند السلام؟","title":"حكم الالتفاف عند السلام وصفته","answer":"الجواب: سنة مستحبَّة، إذا سلَّم ولم يلتفت أجزأه.\nس: مَن يفصل يقول: يُسلم أمامه، ثم يقول: وعليكم ورحمة الله ..؟\nج: لا، السنة [أن] يلتفت للسلام كله، السنة أن يلتفت له، السلام عن يمينه، وعن شماله، هذا هو الثابت في الأحاديث الصَّحيحة.\nس: الالتفات في التَّسليم هل يكون يسيرًا أو يكون ..؟\nج: حتى يُرى خدّه كما قال سعد: يلتفت حتى يُرى خدّه من خلفه، هكذا، يعني: يُبالغ في التَّسليم.","link":"https://binbaz.org.sa/fatwas/24861/حكم-الالتفاف-عند-السلام-وصفته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الالتفاف عند السلام.mp3","categories":["التشهد والتسليم"]},{"id":4578,"question":"زيادة \"وبركاته\"؟","title":"حكم زيادة \"وبركاته\" في التسليم من الصلاة","answer":"الجواب: شاذَّة، شاذَّة؛ لأن الرواية فيها نظر، فيها ضعف، والمحفوظ \"ورحمة الله\" كما في حديث ابن مسعودٍ، وسمرة بن جندب، وسعد بن أبي وقاص.  الحاكم رحمه الله صحَّحها، ولكن في صحَّتها نظر؛ لأنها من رواية علقمة .....، رواية علقمة بالعنعنة عن أبيه، لم يسمعها؛ ولهذا قال ابنُ معين وجماعة: لم يسمع من أبيه. وقال آخرون: سمع من أبيه بعض الشيء . وجاء في بعض رواية مسلم أنه سمع من أبيه.","link":"https://binbaz.org.sa/fatwas/24863/حكم-زيادة-وبركاته-في-التسليم-من-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/زيادة وبركاته عند التسليم من الصلاة.mp3","categories":["التشهد والتسليم"]},{"id":5660,"question":"هل يرفع الإنسانُ السَّبابة عند كل ذكرٍ، سواء في الصلاة أو غيرها، أم عند الدُّعاء؟","title":"ما الأحوال التي يُشرع فيها رفع السَّبابة؟","answer":"الجواب: يُستحبّ رفع السَّبابة عند الشَّهادة من أول ما يجلس إلى أن يُسلم في التَّشهد الأخير، وهكذا في التَّشهد الأول يُشير بالسبابة إلى التوحيد، وعند الدعاء يُحركها قليلًا عند: \"اللهم صلِّ على محمدٍ\"، وعند \"أعوذ بالله من عذاب جهنم\"، وعند الدعاء: \"اللهم أعني على ذكرك\"، عند الدُّعاء يُحركها قليلًا كما فعل النبيُّ ﷺ. س: ما صحة رفع الإنسان السَّبابة والنَّظر إلى السماء بعد الفراغ من الوضوء؟ ج: يستحبّ أن يقول بعد الفراغ من الوضوء: \"أشهد أن لا إله إلا الله وحده لا شريكَ له، وأشهد أنَّ محمدًا عبده ورسوله، اللهم اجعلني من التَّوابين، واجعلني من المتطهرين، سبحانك اللهم وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك اللهم وأتوب إليك\"، وإذا أشار بالسبابة فلا بأس، جاء فيها حديثٌ فيه ضعف، جاء بالإشارة بالسبّاحة .....، وإذا أشار بها للتوحيد فلا حرج.[1]","link":"https://binbaz.org.sa/fatwas/31697/ما-الاحوال-التي-يشرع-فيها-رفع-السبابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 006.mp3","categories":["التشهد والتسليم"]},{"id":5680,"question":"ما حكم الجماعة التي تكون مسبوقة، وتصلي جماعة أخرى بعد الصلاة التي أذن لها مع الإمام الراتب؟","title":"حكم إقامة جماعة ثانية بعد انتهاء الجماعة الأولى في المسجد","answer":"الجواب: لا حرج في هذا، إذا وصلوا والإمام قد صلى يقيمون صلاة لجماعة أخرى ويصلون، كما أقام النبي جماعة أخرى في الشخص الذي دخل وقد فاتته الصلاة، فقال النبي لبعض الحاضرين: من يتصدق على هذا، ويصلي معه؟ يصلون جماعة؛ لأن صلاة الرجل مع الرجل أكمل من صلاته وحده، فإذا فاتته الجماعة، ووجد آخرون صلى معهم جميعًا جماعة، وقد فعله أنس، وغيره من الصحابة. وأما قول من قال من أهل العلم: إنهم لا يصلون جماعة، بل يرجعون إلى بيوتهم، ويصلون فرادى، فهذا القول ليس بشيء، مرجوح وضعيف، بخلاف السنة، وخلاف قواعد الشريعة.  السؤال: من أدرك التشهد الأخير؟ الجواب: الأفضل يدخل معهم، ولو في التشهد الأخير؛ لأن النبي ﷺ قال: ما أدركتكم فصلوا، وما فاتكم فأتموا فإذا أدركهم ما صلوا دخلوا مع الإمام، ولو مع الجماعة. السؤال: ولو أعيدت الصلاة بعد صلاة الفجر في الأوقات المنهية عنه؟ الجواب: ولو ، سواء فجر، ولا عصر، أو غيره إذا جاءهم وهم يصلون دخل معهم، هذا هو الأفضل، هذا هو السنة، ولو قد صلى .","link":"https://binbaz.org.sa/fatwas/980/حكم-اقامة-جماعة-ثانية-بعد-انتهاء-الجماعة-الاولى-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_08.mp3","categories":["صلاة الجماعة","التشهد والتسليم"]},{"id":5726,"question":"يقال: إن الإمام يتحمل بعض الواجبات عن المأمومين، نرجو توضيح ذلك، وبيان ما يتحمله؟","title":"ما يتحمله الإمام عن المأمومين","answer":"الجواب: نعم، الإمام يتحمل بعض الشيء عن المأمومين، ومن ذلك أنه يتحمل السهو عنهم، فإذا سها المأموم ما عليه شيء، إنما يسجد الإمام، ويسجد معه. أما سهوه وحده وهو مع الإمام لا يضره، وليس له أن يسجد وحده إذا كان مع الإمام من أول الصلاة، ويتحمل عنهم، لو ترك التشهد الأول، وقام يقومون معه، يتحمل عنهم هذا التشهد الأول، إذا قام ساهيًا يتبعونه، ويسجد لسجود للسهو.  وعند بعض أهل العلم يتحمل عنهم أيضًا قراءة الفاتحة، عند الأكثرين، يتحمل عنهم الفاتحة، ما تجب عليهم، لكن الأصح أنها تجب على المأمومين، وأنه لا يتحملها عنهم، هذا هو المختار؛ لعموم الأدلة، لقوله ﷺ: لا صلاة لمن لم يقرأ بفاتحة الكتاب في الصحيحين.  وقوله ﷺ في الرواية الأخرى: لعلكم تقرؤون خلف الإمام قلنا: نعم، قال: لا تفعلوا إلا بفاتحة الكتاب، فإنه لا صلاة لمن لم يقرأ بها في أحاديث أخرى.","link":"https://binbaz.org.sa/fatwas/1035/ما-يتحمله-الامام-عن-المامومين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_57.mp3","categories":["صلاة الجماعة","التشهد والتسليم"]},{"id":5761,"question":"الإمام إذا سلم عن يمينه فتبعه المأمومون، ثم سلم عن يساره فاتبعوه؟","title":"حكم متابعة الإمام في كل تسليمة","answer":"الجواب: هذا يسأل عما إذا كان المأمومون يسلمون مع الإمام بعد ما يسلم الأولى يسلمون الأولى، وبعد الثانية الثانية.  الجواب: هذا لا بأس به، صحيح لا يضر، لكن السنة والأولى والأفضل أن يتأخروا حتى يسلم الثانية، لا يعجلوا إذا سلم الأولى، لا يسلمون حتى يسلم الثانية على ظاهر الأحاديث، ومن باب كمال المتابعة.  أما إذا سلم بعد الأولى سلم الأولى، وبعد الثانية سلم الثانية، فالصلاة مجزئة، ولا يكون عليه حرج، ولا إثم لكن ترك ما هو الأفضل والأكمل والأحوط.  فالذي ينبغي أن يتأنوا ولا يعجلوا حتى يسلم الإمام الثانية، فإن سلم الثانية سلموا، لقول النبي ﷺ: وإذا كبر فكبروا وإذا ركع فاركعوا فلا تركع حتى يركع، فيتأنون حتى يسلم الثانية، هذا هو الأحوط، والأكمل في الاتباع، وإذا سلم الأولى بعد الأولى، والثانية بعد الثانية نرجو ألا يكون عليه حرج، ولكنه ترك ما هو الأحوط والأفضل.  السؤال: في حديث في صحيح البخاري ما معناه ما يدل على أنه لو سلم عن يمينه بعد الإمام بعد التسليمة الأولى مباشرة لعله أن تكون هذه التسليمة، ولو أحدث تكون صلاته صحيحة؟ الجواب: هذا فيه خلاف بين العلماء، والأكثرون يقولون: تكفي الأولى إذا سلم الأولى كفى، ولو أحدث بعدها فصلاته مجزئة، وذهب بعض أهل العلم إلى أنه لا بدّ من تسليمتين، فلا يختم الصلاة، ولا ينتهي منها إلا بالتسليمة الثانية. فعلى هذا لو أحدث بين التسليمتين بطلت الصلاة، فعليه أن يعيدها وهذا هو الأرجح، الأرجح أنه لا بدّ من تسليمتين، وينبغي له أن لا يعجل، ويرى الجمهور أنه إذا سلم الأولى أجزأت، والثانية سنة غير واجبة عندهم، تكفي الأولى، ولكن الأرجح والأفضل في الأدلة أنهما واجبتان جميعًا، من أركان الصلاة ينبغي المحافظة عليها، وقال: صلوا كما رأيتموني أصلي.  وفق الله الجميع، وصلى الله وسلم على نبينا محمد وعلى آله وصحبه.","link":"https://binbaz.org.sa/fatwas/1068/حكم-متابعة-الامام-في-كل-تسليمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_82.mp3","categories":["صلاة الجماعة","التشهد والتسليم"]},{"id":5788,"question":"إذا سها المصلي في الصلاة، وسلم الإمام وهو لم يقل التشهد، فهل يسلم بعد الإمام، أم يتأخر لكي يقول التشهد؟","title":"من سها حتى سلم الإمام ولم يقرأ التشهد","answer":"الجواب: إذا سلم الإمام وأنت ما كملت التشهد؛ فعليك أن تكمله، ثم تسلم، أول تكمل التشهد والصلاة على النبي ﷺ ثم تسلم، وإن كملت بالتعوذ بالله من عذاب جهنم، وعذاب القبر، وإلى آخره فهذا أفضل؛ لأن هذا التعوذ قد قال بعض أهل العلم بالوجوب، فالأولى أن تكمله، ثم تسلم بعد ذلك. وينبغي لك أن لا تغفل، بل عليك أن تعتني بقراءة التحيات حتى تسلم بعد إمامك مباشرة، فإياك والغفلة حتى يسلم إمامك وأنت ساه لاه، عليك أن تجتهد حتى تقرأ التحيات، والصلاة على النبي ﷺ وتقول الدعاء قبل أن يسلم إمامك، لكن لو فرضنا أنه سلم، وأنت ما كملت؛ كمل، ثم تسلم.","link":"https://binbaz.org.sa/fatwas/1116/من-سها-حتى-سلم-الامام-ولم-يقرا-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_123.mp3","categories":["الأدعية والأذكار","التشهد والتسليم"]},{"id":6002,"question":"كثير من الناس بعد التسليم من الصلاة يقول: لا نعبد، ولا نشكر إلا إياه، فهل هذا صحيح، حيث قال تعالى: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14]؟","title":"حكم قول: (لا نعبد ولا نشكر إلا إياه) بعد الصلاة","answer":"الجواب: بعد السلام ما يقال هذا الكلام، بعد السلام يقول: أستغفر الله، أستغفر الله، أستغفر الله، اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال، والإكرام، هذا المشروع بعد السلام للإمام، والمنفرد، والإمام إذا سلم من الفريضة يقول: أستغفر الله، أستغفر الله، أستغفر الله، اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال، والإكرام، ثم ينصرف بوجهه إلى الناس؛ لأنه يقوله وهو مستقبل القبلة.  إذا كان إمامًا يقوله، وهو مستقبل القبلة، ثم ينصرف، ويعطي الجماعة وجهه، ويقابلهم، ثم يقول: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، وهكذا المأمومون، وهكذا المنفرد، يقول: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وإن زاد يحيي ويميت؛ فلا بأس، قد جاء في بعض الروايات، والله على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبد إلا إياه، له النعمة، وله الفضل، وله الثناء الحسن، لا إله إلا الله، مخلصين له الدين، ولو كره الكافرون، اللهم لا مانع لما أعطيت، ولا  معطي لما منعت، ولا ينفع ذا الجد منك الجد، هذا ثبت من الحديث المغيرة في الصحيحين، ومن حديث الزبير عند مسلم. وكذلك يسبح الله ثلاثًا وثلاثين، ويحمد الله ثلاثًا وثلاثين، ويكبر الله ثلاثًا وثلاثين، ويقول تمام المائة: لا إله إلا الله، وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، بعد كل صلاة قال فيه النبي ﷺ من قال هذا؛ غفرت خطاياه، وإن كانت مثل زبد البحر خرّجه مسلم في الصحيح. ويستحب مع ذلك أن يقرأ آية الكرسي بعد كل صلاة بعد هذا، ويقرأ قل هو الله أحد، والمعوذتين كلها هذا مستحب، أما: \"لا نعبد إلا إياه، ولا نشكر إلا إياه\" فما نعلم جاء فيه شيء من النصوص. س:...؟ الجواب: مخير إن قال: سبحان الله، والحمد لله، والله أكبر ثلاثًا وثلاثين، فهذا أحسن، وأخصر، وإن قال: سبحان الله ثلاثًا وثلاثين، والحمد لله ثلاثًا وثلاثين، وكبر الله ثلاثًا وثلاثين؛ فلا بأس، كله واسع.","link":"https://binbaz.org.sa/fatwas/1388/حكم-قول-لا-نعبد-ولا-نشكر-الا-اياه-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_344.mp3","categories":["الأدعية والأذكار","التشهد والتسليم"]},{"id":7752,"question":"يقول المستمع من الرس: إذا حضر المأموم الصلاة مع الإمام بعد أن صلى ركعة من صلاة الظهر؛ فهل يقرأ التشهد الأول عند جلوس الإمام والمأموم لم يصل إلا ركعة واحدة؟","title":"حكم قراءة التشهد الأول لمأموم فاتته ركعة مع الإمام","answer":"الجواب: لا يلزمه ذلك لأن هذا ليس محل تشهده، إذا أدرك ركعة واحدة مع الإمام في الظهر أو في العصر أو في المغرب أو في العشاء أو الفجر فإنه لا يلزمه قراءة التشهد إذا جلس مع الإمام في الركعة الثانية، هو محل التشهد لمن صلى مع الإمام من أول الصلاة، أما هذا فمحل تشهده يأتي إذا أتى بالركعة الثانية، فإن قرأه فلا حرج إن شاء الله. نعم.\nالمقدم: لكن إذا لم يرد القراءة ما الذي يصنع في هذا الجلوس؟\nالشيخ: يسكت، إما يسكت وإلا يقرأ مثله لكن لا يلزمه أن يقرأ التشهد؛ لأن هذا ليس محل قراءته، ولكن كونه يقرؤه ويأتي به خير من السكوت؛ لأنه فضل ولأنه ذكر، فإتيانه به خير. نعم.","link":"https://binbaz.org.sa/fatwas/4952/حكم-قراءة-التشهد-الاول-لماموم-فاتته-ركعة-مع-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_043/04304.mp3","categories":["التشهد والتسليم"]},{"id":7763,"question":"هذه رسالة من عبد الرقيب معطي الرياض، يقول: ما حكم السلام على اليسار بعد انتهاء الصلاة؟ وما حكم الانفتال على اليسار أيضاً؟","title":"أحكام السلام والانصراف بعد انتهاء الصلاة","answer":"الجواب: الجمهور على أن الواجب تسليمة واحدة يسلمها عن يمينه، والأصح أنه لابد من تسليمتين وإن كان خلاف قول الجمهور؛ لأن الرسول ﷺ كان يسلم تسليمتين ويقول: صلوا كما رأيتموني أصلي.\nفالواجب أن يسلم الإمام، وهكذا المأموم وهكذا المنفرد تسليمتين، والأفضل عن يمينه وشماله، يلتفت عن يمينه ويقول: السلام عليكم ورحمة الله، وعن يساره كذلك، هذا هو المشروع، وهو واجب في أصح قولي العلماء يعني التسليمتين، أما كونه يلتفت عن يمينه وشماله، هذا مستحب وهو أفضل.\nوأما الانصراف بعد السلام عن يمينه وشماله فلا حرج، النبي ﷺ كان ينصرف عن يمينه وعن شماله، كل هذا ثابت، إن انصرف عن يمينه فلا بأس أو عن شماله فلا بأس، قد ثبت عنه ﷺ أنه كان ربما انصرف عن يمينه وربما انصرف عن شماله من مكانه عليه الصلاة والسلام. نعم.\nالمقدم: لكن لو بدأ بالسلام على شماله هل في ذلك شيء؟\nالشيخ: يصح، لكن خالف السنة، خالف السنة.\nالمقدم: يعني لا يؤاخذ على ذلك؟\nالشيخ: لا، يصح، لكنه خالف السنة. نعم.\nالالتفات مستحب وليس بواجب، وكذلك مسألة قد يعني تخفى على بعض الناس وهي: مسألة الإمام إذا سلم من الصلاة، السنة أنه ينصرف للمأمومين ويعطيهم وجهه ولا يطول بقاءه مستقبل القبلة؛ لأنه إنما استدبرهم من أجل حاجة الصلاة، فإذا فرغ منها زالت الحاجة، فشرع له أن يستقبلهم ويجعل وجهه إلى وجوههم، هذا هو الأدب الشرعي، لكن بعدما يستغفر ثلاثاً، وبعد ما يقول: «اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال والإكرام» بعد هذا ينصرف إليهم ويعطيهم وجهه، يقابلهم، لا يكن يميناً ولا شمالاً، بل يقابلهم مقابلة كفعل النبي ﷺ، ولكن يكون بعد أن يقول: «أستغفر الله، ثلاثاً، اللهم أنت السلام ومنك السلام، تباركت يا ذا الجلال والإكرام!» يقوله الإمام ثم ينصرف إلى المأمومين، ويعطيهم وجهه مستوياً . نعم. إن شاء انصرف عن يمينه وإن شاء انصرف عن شماله. نعم . لكن يقابلهم مقابلة. نعم. ثم يأتي ببقية الأذكار، إذا انصرف أتى ببقية الأذكار: «لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله، لا نعبد إلا إياه، له النعمة وله الفضل وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون، اللهم لا مانع لما أعطيت ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد» ثبت عنه عليه السلام أنه كان يقول هذا بعد السلام في الظهر والعصر والمغرب والعشاء والفجر، فيشرع للمأموم والإمام والمنفرد هذه الأذكار الشرعية، ثم يقول بعدها: (سبحان الله والحمد لله والله أكبر) ثلاثاً وثلاثين مرة، هذا الأفضل، بعد هذا يقول: (سبحان الله والحمد لله والله أكبر) ثلاثاً وثلاثين مرة، يكون الجميع تسعة وتسعين، ثم يختم هذا كله بلا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، جاء في الحديث: إن العبد إذا قال هذا غفرت خطاياه وإن كانت مثل زبد البحر وهذا فضل عظيم، وإن شاء قال: سبحان الله والحمد لله ولا إله إلا الله والله أكبر؛ خمسة وعشرين مرة، هذا نوع من الأذكار، سبحان الله والحمد لله ولا إله إلا الله والله أكبر، خمس وعشرين مرة ، كل هذا مشروع وحسن. نعم.\nالمقدم: لكن بالنسبة للتهليل والتكبير، هل هو بعد الصلوات الخمس أم بعد بعضها؟\nالشيخ: لا، بعد الجميع، بعد الصلوات الخمس، لكن تزداد المغرب والفجر بتهليلات عشر زيادة، يقول: (لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت، وهو على كل شيء قدير) عشر مرات بعد المغرب وبعد الفجر زيادة. نعم.\nالمقدم: بعض الناس بالنسبة لانصراف الإمام أو التفات الإمام للمأمومين يقول: لا يجوز للمأموم أن يفارق المسجد ما لم ينصرف الإمام إليه، هل هذا صحيح أم لا؟\nالشيخ: محتمل، والأقرب أنه غير صحيح، لكنه يستحب له، يستحب له، والأولى له ألا ينصرف لقول النبي ﷺ: إني إمامكم، فلا تسبقوني بالركوع ولا بالسجود ولابالقيام ولا بالانصراف، والمشهور في الانصراف هنا أنه السلام، ما هو بالانصراف إليهم، المشهور بالانصراف أنه السلام مثلما قال ثوبان: كان النبي ﷺ إذا انصرف من صلاته استغفر ثلاثاً  انصرف يعني سلم.\nأما الانصراف إليهم فالأولى أن يصبروا حتى ينصرف إليهم، هذا هو الأولى، ولكن لو قاموا قبل ذلك فالظاهر أنه لا حرج، إذ الانصراف في الحديث المراد به السلام، نعم. هذا هو الظاهر من الأحاديث. نعم.","link":"https://binbaz.org.sa/fatwas/4972/احكام-السلام-والانصراف-بعد-انتهاء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_045/04505.mp3","categories":["التشهد والتسليم"]},{"id":8121,"question":"ثاني يقول: إذا أطال الإمام في التشهد الأول الجلوس، هل نصلي على النبي ﷺ بعد كمال التشهد، أم نقرأ التشهد ونصمت حتى يقوم الإمام؟","title":"حكم الصلاة على النبي في التشهد الأول","answer":"الجواب: السنة أن يقرأ الصلاة على النبي ﷺ، يقرأ المصلي في التشهد الصلاة على النبي ﷺ إذا تيسر، سواء كان إماماً أو منفرداً أو مأموماً؛ لأن الرسول ﷺ لما سئل عن ذلك بين لهم كيفية الصلاة، ولم يقل: هذا في التشهد الأخير فقط، بل أطلق، فدل ذلك على أنه يشرع في التشهد الأول والأخير جميعاً، فإذا قال: أشهد أن لا إله إلا الله، وأشهد أن محمداً عبده ورسوله يقول: اللهم صل على محمد وعلى آل محمد إلى آخره، في التشهد الأول والأخير جميعاً، هذا هو الأفضل، وهذا هو الأرجح، وإن قام الإمام ولم يتمكن من قولها فلا بأس، يقوم مع الإمام ويكفيه أن يقول: وأشهد أن محمداً عبده ورسوله، لكن إذا تمكن يأتي بالصلاة على النبي ﷺ، أو كان إماماً أو منفرداً يأتي بالصلاة على النبي ﷺ، هذا هو الأفضل، وهو ظاهر الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/5921/حكم-الصلاة-على-النبي-في-التشهد-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_087/08708.mp3","categories":["التشهد والتسليم"]},{"id":8367,"question":"إذا أطال الإمام الجلوس في التشهد الأول، ماذا يقرأ المصلي، أم يتوقف إلى الصلاة على النبي ﷺ ثم يعيد قراءتها ثانية، أو يستمر حتى نهاية التشهد والدعاء، وهذا السؤال جاءنا من الأخوين ناصر ومحمد عبد الرحمن العيبان من الرياض؟","title":"ماذا يفعل المأموم إذا أطال الإمام الجلوس في التشهد الأول؟","answer":"الجواب: إذا أطال الإمام الجلوس في التشهد الأول، فالمأموم يكرر التحيات والصلاة على النبي ﷺ، ويكفي؛ لأن السنة ألا يزيد على الصلاة على النبي ﷺ في التشهد الأول، فإذا أطال الإمام الجلوس، ولا ينبغي له أن يطيل، فإن المأموم يكرر التحيات، أو يكرر الصلاة على النبي صلى الله عليه وسلم، أو يكررهما جميعاً، أو يسكت، ولا حرج عليه في ذلك، أما الإمام فالسنة له ألا يطيل، بل متى فرغ من التشهد الأول وصلى على النبي ﷺ قام، وإن لم يصل على النبي ﷺ في التشهد الأول، فلا حرج.\nالمقصود أن الواجب إلى قوله: أشهد أن لا إله إلا الله وأشهد أن محمداً عبده ورسوله، فإن قام عند هذا فلا بأس، وإن صلى على النبي ﷺ فهو أفضل في أصح قولي العلماء، ثم يقوم إلى الثالثة، فإذا أطال زيادة على هذا فهو مكروه، لا ينبغي له أن يطيل، لكن لو أطال فإن المأموم يكرر التحيات والصلاة على النبي صلى الله عليه وسلم، أو يسكت ولا حرج.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6216/ماذا-يفعل-الماموم-اذا-اطال-الامام-الجلوس-في-التشهد-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11407.mp3","categories":["التشهد والتسليم"]},{"id":9698,"question":"أخيراً يسأل عن مجموعة أمور فيقول: هل تجوز التسليمة الواحدة في الصلاة، يقصد هل تكفي التسليمة الواحدة في الصلاة؟ وهل يكفي في إقامة الصلاة أن يقول الإنسان: قد قامت الصلاة مرة واحدة أم لا، أفيدونا أفادكم الله؟","title":"حكم من سلم تسليمة واحدة في الصلاة","answer":"الجواب: المحفوظ عن النبي ﷺ تسليمتان، وذهب الجمهور من أهل العلم إلى أنها تكفي التسليمة الواحدة وأنها تجزي، ولكن الصحيح والصواب أنها لا تكفي بل لا بد من تسليمتين؛ لأن هذا هو المحفوظ عن النبي ﷺ، وقد قال: صلوا كما رأيتموني أصلي عليه الصلاة والسلام، فالواجب على الأئمة وعلى غيرهم أن يسلموا تسليمتين، هذا هو المعتمد.","link":"https://binbaz.org.sa/fatwas/7845/حكم-من-سلم-تسليمة-واحدة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_252/25205.mp3","categories":["التشهد والتسليم"]},{"id":9768,"question":"يقول: عندنا في بلدنا الكثير من الناس لا يحفظون التحيات -التشهد- فهل تصح صلاتهم من غير التشهد، علماً بأنهم أميون لا يقرءون ولا يكتبون، أم يلزمنا أن نعلم من استطعنا منهم؟ جزاكم الله خيراً.","title":"الواجب على من لا يحفظ التشهد في الصلاة","answer":"الجواب: يلزمهم التعلم لجميع ما يجب في صلاتهم، يتعلمون الفاتحة، يتعلمون التشهد، يتعلمون جميع ما يلزم في الصلاة، والواجب عليكم أن تعلموهم، وترشدوهم وتوجهوهم إلى الخير حتى يفهموا ما أوجب الله عليهم في الصلاة، وهكذا في الزكاة، وهكذا في الصيام، وهكذا في الحج إذا حجوا.\nالمقصود أن الواجب على المؤمن أن يتفقه في صلاته، وأن يتعلم ما يجب عليه، وأن لا يتساهل في ذلك؛ لأن الله سبحانه خلقه للعبادة، كما قال : وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]، وأمر بذلك، قال سبحانه: يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21]، وهذه العبادة يجب أن تعرفها أيها المؤمن! ويجب أن تعرفها المؤمنة، وهي طاعة الله ورسوله، والاستقامة على دينه، هذه هي العبادة التي خلقنا لها، أن نعبد الله وحده بطاعة أوامره وترك نواهيه، وأعظم ذلك توحيده والإخلاص له، والشهادة بأنه لا معبود حق إلا هو سبحانه وتعالى، والشهادة بأن محمداً عبد الله ورسوله، ثم الصلاة وبقية أمور الدين، يقول النبي ﷺ: من يرد الله به خيراً يفقهه في الدين، ومن علامات الخير، أن لله يفقه العبد في دينه، ومن علامات سوء العاقبة أن لا يتعلم وأن لا يتفقه، نسأل الله العافية، نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/7933/الواجب-على-من-لا-يحفظ-التشهد-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_257/25707.mp3","categories":["التشهد والتسليم"]},{"id":10677,"question":"رسالة وصلت إلى البرنامج من الأخت في الله: (ل. ر. ع) من الرياض، بعثت بعدد من الأسئلة، من بينها سؤال يقول: ماذا يجب على من دعا بعد التشهد الأول من الركعة الرباعية سهواً؟","title":"حكم الدعاء بعد التشهد الأول سهواً","answer":"الجواب: ليس عليه شيء، إذا دعا ليس عليه شيء، إنما السنة أن يكون الدعاء في التشهد الأخير، فإذا دعا في التشهد الأول فليس عليه شيء. نعم.","link":"https://binbaz.org.sa/fatwas/8852/حكم-الدعاء-بعد-التشهد-الاول-سهوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33002.mp3","categories":["التشهد والتسليم"]},{"id":11012,"question":"هل تقرأ الصلاة على النبي ﷺ في التشهد الأول، وهل للإنسان أن يتورك في صلاة الفجر؟","title":"حكم الصلاة على النبي في التشهد الأوسط والتورك في الفجر","answer":"الجواب:  إن قرأت الصلاة على النبي ﷺ في التشهد الأول فهو أفضل، إذا أتى بالصلاة على النبي ﷺ في التشهد الأول هذا أفضل على الصحيح، وإن تركه فلا بأس، إذا قام بعد الشهادتين إلى الثالثة فلا حرج، وإن صلى على النبي ﷺ ثم قام إلى الثالثة فهذا أفضل في أصح قولي العلماء، والأفضل الافتراش في التشهد الأول وبين السجدتين، يجلس على اليسرى وينصب اليمنى، هذا هو الأفضل وإن تورك فلا حرج، أو كان يشق عليه الافتراش فلا حرج، المقصود أن التورك في التشهد الأخير في الظهر والعصر والمغرب والعشاء هذا هو الأفضل، أما التشهد الأول فالسنة فيه الافتراش، يفترش اليسرى، وينصب اليمنى، وهكذا بين السجدتين، وهكذا في صلاة الفجر والجمعة الافتراش، لكن من شق عليه ذلك فلا حرج، ويتورك إذا سجد، فلا بأس، كلها أمور مستحبة، ليست فريضة، الافتراش والتورك كله سنة، فلو أنه افترش في محل تورك، أو تورك في محل افتراش فلا حرج، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9198/حكم-الصلاة-على-النبي-في-التشهد-الاوسط-والتورك-في-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_366/36614.mp3","categories":["التشهد والتسليم"]},{"id":11019,"question":"هل تقرأ الصلاة على النبي ﷺ في التشهد الأول، وهل للإنسان أن يتورك في صلاة الفجر؟","title":"حكم الصلاة على النبي في التشهد الأوسط والتورك في الفجر","answer":"الجواب:  إن قرأت الصلاة على النبي ﷺ في التشهد الأول فهو أفضل، إذا أتى بالصلاة على النبي ﷺ في التشهد الأول هذا أفضل على الصحيح، وإن تركه فلا بأس، إذا قام بعد الشهادتين إلى الثالثة فلا حرج، وإن صلى على النبي ﷺ ثم قام إلى الثالثة فهذا أفضل في أصح قولي العلماء، والأفضل الافتراش في التشهد الأول وبين السجدتين، يجلس على اليسرى وينصب اليمنى، هذا هو الأفضل وإن تورك فلا حرج، أو كان يشق عليه الافتراش فلا حرج، المقصود أن التورك في التشهد الأخير في الظهر والعصر والمغرب والعشاء هذا هو الأفضل، أما التشهد الأول فالسنة فيه الافتراش، يفترش اليسرى، وينصب اليمنى، وهكذا بين السجدتين، وهكذا في صلاة الفجر والجمعة الافتراش، لكن من شق عليه ذلك فلا حرج، ويتورك إذا سجد، فلا بأس، كلها أمور مستحبة، ليست فريضة، الافتراش والتورك كله سنة، فلو أنه افترش في محل تورك، أو تورك في محل افتراش فلا حرج، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9198/حكم-الصلاة-على-النبي-في-التشهد-الاوسط-والتورك-في-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_366/36614.mp3","categories":["التشهد والتسليم"]},{"id":11427,"question":"ما حكم تحريك الأصبع في الصلاة مع التفصيل في جميع الحالات الموجبة، أو المستحبة للتحريك؟ جزاكم الله خيرًا.","title":"تحريك السبابة أثناء التشهد","answer":"الجواب:  السنة إذا جلس للتشهد الأول، والتشهد الأخير يقبض أصابعه، ويشير بالسبابة، يرفع السبابة فقط، ويقبض أصابعه كلها، أو يحلق الإبهام مع الوسطى، فعل النبي هذا وهذا -عليه الصلاة والسلام- تارة وتارة، تارة يقبضها كلها، ويشير بالسبابة يقيمها إشارة للوحدانية، وتارة يحلق الإبهام مع الوسطى، ويقبض الخنصر والبنصر، ويشير بالسبابة، أما التحريك فيكون عند الدعاء في التشهد الأخير، عند الدعاء خاصة، كان النبي ﷺ: يحرك إصبعه عند الدعاء نعم.  المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9609/تحريك-السبابة-اثناء-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38025.mp3","categories":["التشهد والتسليم"]},{"id":11930,"question":"يقول: عندنا في بلدنا الكثير من الناس لا يحفظون التحيات -التشهد- فهل تصح صلاتهم من غير التشهد، علمًا بأنهم أميون، لا يقرؤون ولا يكتبون، أم يلزمنا أن نعلم من استطعنا منهم جزاكم الله خيرًا؟","title":"حال صلاة من لا يحسن قراءة التشهد","answer":"الجواب:  يلزمهم التعلم لجميع ما يجب في صلاتهم، يتعلمون الفاتحة، يتعلمون التشهد، يتعلمون جميع ما يجهل في الصلاة، والواجب عليكم أن تعلموهم وترشدوهم وتوجهوهم إلى الخير حتى يفهموا ما أوجب الله عليهم في الصلاة، وهكذا في الزكاة، وهكذا في الصيام، وهكذا في الحج إذا حجوا. المقصود: أن الواجب على المؤمن أن يتفقه لصلاته، وأن يتعلم ما يجب عليه، وأن لا يتساهل في ذلك، لأن الله سبحانه خلقه للعبادة، كما قال : وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]، وأمر بذلك، قال سبحانه: يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21]، وهذه العبادة يجب أن تعرفها أيها المؤمن، ويجب أن تعرفها المؤمنة، وهي طاعة الله ورسوله، والاستقامة على دينه هذه هي العبادة التي خلقنا لها، أن نعبد الله وحده بطاعة أوامره، وترك نواهيه، وأعظم ذلك توحيده، والإخلاص له، والشهادة بأنه لا معبود حق إلا هو  والشهادة بأن محمد عبد الله ورسوله، ثم الصلاة، وبقية أمور الدين، يقول النبي ﷺ: من يرد الله به خيرًا؛ يفقهه في الدين،... فمن علامات الخير: أن الله يفقه العبد في دينه، ومن علامات سوء العاقبة ألا يتعلم، وألا يتفقه، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10114/حال-صلاة-من-لا-يحسن-قراءة-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_427/42707.mp3","categories":["التشهد والتسليم"]},{"id":12170,"question":"من الجمهورية العربية اليمنية ناحية صباح قرية زخم، رسالة بعث بها أحد المستمعين من هناك هو: أحمد علي ناجي محمد الصباحي، الأخ أحمد بعث برسالة ضمنها تسعة أسئلة، في أحد أسئلته يقول: صليت في بعض المساجد، فوجدت لهم طريقة عجيبة في التسليم، حيث يسلم الإمام التسليمة الأولى، ويسلم المصلون خلفه، ثم يسلم الثانية ويسلمون، فهل ذلك صحيح؟","title":"حكم تسليم المؤتمين بعد التسليمة الأولى للإمام","answer":"الجواب:  السنة أن يسلم الإمام التسليمتين جميعًا، ثم يسلم المأمومون بعده، هذا هو السنة، ولكن هذا الذي فعله هؤلاء صحيح، صلاتهم صحيحة إذا سلموا الأولى بعد الأولى، والثانية بعد الثانية؛ فلا حرج في ذلك، لكنه خلاف السنة، خلاف الأفضل، بل السنة أن ينتظروا حتى يسلم إمامهم التسليمتين، ثم يسلموا بعده، هذا هو السنة، وهذا هو المعروف من فعل النبي ﷺ والصحابة فيما بلغنا، لكن إذا كانوا سلموا بعد التسليمة الأولى، ثم سلموا بعد التسليمة الثانية؛ صحت الصلاة، ولا شيء عليه؛ لأنهم لم يسابقوه ما سبقوه بشيء، نعم.","link":"https://binbaz.org.sa/fatwas/10356/حكم-تسليم-الموتمين-بعد-التسليمة-الاولى-للامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_442/44208.mp3","categories":["التشهد والتسليم"]},{"id":12540,"question":"يسأل أخونا أيضًا ويقول: أمرنا بالاستعاذة من فتنة المحيا، وفتنة الممات، والمسيح الدجال، حبذا لو شرحتم لنا هذا، جزاكم الله خيرًا.","title":"ما الحكمة من الاستعاذة من فتنة المحيا والممات والمسيح الدجال؟","answer":"الجواب:  هذا مشروع للمؤمن والمؤمنة في كل صلاة، السنة لكل مؤمن، ولكل مؤمنة أن يختم صلاته بالاستعاذة بالله من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال، ثبت عنه ﷺ في أحاديث كثيرة أنه كان بعدما يتشهد في آخر الصلاة قبل أن يسلم يستعيذ بالله من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال ، وكان يأمر بهذا ويقول: إذا تشهد أحدكم؛ فليستعذ بالله من أربع، يقول: اللهم إني أعوذ بك من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال فالمشروع للمؤمن وللمؤمنة التعوذ من هذه الأربعة. وذهب جمهور أهل العلم إلى أن هذا سنة مؤكدة، وروي عن طاوس التابعي الجليل ما يدل على أن ذلك واجب، وروي عنه أنه أمر ولده لما لم يقلها في الصلاة أن يعيد الصلاة، فهذا يدل على تأكد هذه الدعوات، وأنه ينبغي للمؤمن أن لا يدعها في أي صلاة النافلة والفريضة قبل أن يسلم، يقول: أعوذ بالله من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال وإن شاء قال: ربنا آتنا في الدنيا حسنة، وفي الآخرة حسنة، وقنا عذاب النار، وعذاب القبر، وفتنة المحيا والممات، وفتنة المسيح الدجال. فهي دعوات عظيمة، قال أنس : كان أكثر دعاء النبي ﷺ: ربنا آتنا في الدنيا حسنة، وفي الآخرة حسنة، وقنا عذاب النار فإذا دعا بذلك في آخر الصلاة؛ كان حسنًا. وهكذا في السجود إذا دعا بذلك؛ لا بأس، فالسجود محل للدعاء، يقول النبي ﷺ: أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء ويقول -عليه الصلاة والسلام-: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء؛ فقمن أن يستجاب لكم المعنى: حري أن يستجاب لكم. نعم. المقدم: جزاكم الله خيرًا، كأنه يطلب التمثيل لفتنة الممات، وفتنة المسيح الدجال، شيخ عبدالعزيز، وفتنة المحيا أيضًا؟ الشيخ: الإنسان معرض للفتن في حياته، وعند الموت، وقد يعرض في الحياة للمعاصي، قد يعرض للبدع، قد يعرض للكفر بالله  ويفتن إما بسبب المال، أو بسبب الشهوات والمعاصي، أو بسبب جلساء السوء، فيقع فيما يغضب الله عليه من كفر، أو بدعة، أو معصية، في حال حياته، أو عند الموت -نسأل الله العافية- وقد يفتن بـالمسيح الدجال إذا تأخر زمانه، فإن المسيح يخرج في آخر الزمان، يدعي أنه نبي، ثم يدعي أنه رب العالمين، ويتبعه جم غفير من الناس -نعوذ بالله- ويهلكون بأسبابه. فالإنسان يسأل ربه أن يعيذه من هذه الأمور؛ لأنه لا يدري هل يسلم، أو ما يسلم؟! فيسأل ربه ذلك العافية من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال ، هو بحاجة إلى هذا الدعاء؛ حتى لا يفتن في حياته، ولا عند موته، وحتى لا يدرك المسيح الدجال فيفتن به -نسأل الله السلامة- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10740/ما-الحكمة-من-الاستعاذة-من-فتنة-المحيا-والممات-والمسيح-الدجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_409/40902.mp3","categories":["الأدعية والأذكار","التشهد والتسليم"]},{"id":12589,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة يسأل أخونا الإدريسي مولاي عبدالرحمن من المملكة المغربية، يسأل ويقول: هل يجوز لنا أن نسيد محمدًا ﷺ داخل الصلاة؟ وما حكم من يسيده داخل الصلاة؟ وما حكم من لم يسيده داخل الصلاة؟ جزاكم الله خيرًا.","title":"حكم إطلاق لفظ سيدنا على النبي في الصلاة وخارجها","answer":"الجواب:  المشروع في الصلاة عدم التسييد؛ لأنه لم يرد في النصوص، وإنما علمهم أن يقولوا -عليه الصلاة والسلام-: اللهم صل على محمد، وعلى آل محمد، كما صليت على إبراهيم، وعلى آل إبراهيم، إنك حميد مجيد، اللهم بارك على محمد، وعلى آل محمد، كما باركت على إبراهيم، وعلى آل إبراهيم، إنك حميد مجيد. فالمشروع هكذا كما علمهم النبي ﷺ لكن لو أن الإنسان قال: اللهم صل على سيدنا محمد؛ لا بأس، لا حرج عليه؛ لأن محمد سيد ولد آدم -عليه الصلاة والسلام- فمن قال؛ لا حرج عليه، ومن تركها لا حرج عليه. والأفضل: الترك في التشهد، وفي الأذان، يقول: أشهد أن محمدًا رسول الله، كما علم النبي ﷺ أصحابه ذلك، كان بلال يؤذن بهذا، وهكذا أبو محذورة، ولو أن مؤذنًا قال: أشهد أن سيدنا محمد رسول الله؛ صح، لكنه خلاف السنة، ما كان النبي ﷺ يقول هكذا، ولا علمنّا الصحابة ذلك.  وإنما المشروع أن يقول: أشهد أن محمدًا رسول الله في الأذان والإقامة، لكن لو قال: إن سيدنا محمد، هو صادق، هو سيده، لكن لم يشرع هذا، والمسلمون عليهم التقيد في العبادات؛ لأنها توقيفية. فعلى المسلم أن يتقيد بالعبادة بما ورد عن الشرع، ولا يزيد، ففي التحيات يقول: اللهم صل على محمد، وعلى آل محمد كما جاء في النصوص، وفي الأذان يقول: أشهد أن محمدًا رسول الله، وفي الإقامة كذلك. وأما في غير هذا إذا قال: أشهد أن سيدنا محمدًا رسول الله، أو اللهم صل على سيدنا محمد، فلا حرج في ذلك؛ لأنه سيد ولد آدم -عليه الصلاة والسلام- قال -عليه الصلاة والسلام-: أنا سيد ولد آدم ولا فخر. فالمقصود: هو أفضل الخلق -عليه الصلاة والسلام- لكن علينا أن نتقيد بما شرع لنا، لا نزيد، ولا ننقص؛ لأن هذا هو الذي ينبغي لنا؛ لقوله ﷺ في الحديث الصحيح يقول ﷺ: اللهم صل عليه وسلم: من أحدث في أمرنا هذا ما ليس منه؛ فهو رد من عمل عملًا ليس عليه أمرنا؛ فهو رد. فالتقيد بما علمنا إياه، وشرعه لنا هو الذي ينبغي لنا، ويقول ﷺ: إياكم ومحدثات الأمور؛ فإن كل محدثة بدعة، وكل بدعة ضلالة ويقول الرب : لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] ويقول -جل وعلا: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21].  فالمشروع للمسلمين التقيد بما علمهم إياه نبيهم -عليه الصلاة والسلام- وما شرعه لهم في الأقوال والأعمال. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10806/حكم-اطلاق-لفظ-سيدنا-على-النبي-في-الصلاة-وخارجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_413/41309.mp3","categories":["التشهد والتسليم"]},{"id":12758,"question":"بالنسبة للمرأة كيف تكون جلسة التشهد الأول والأخير في الصلاة الرباعية؟","title":"كيفية جلوس المرأة في التشهد","answer":"الجواب:  الصواب أنها كالرجل؛ لقول النبي ﷺ: صلوا كما رأيتموني أصلي ولم يقل هذا للرجال خاصة، بل قال ﷺ: صلوا كما رأيتموني أصلي فالمرأة والرجل في هذا سواء بين السجدتين تجلس على رجلها اليسرى تفرشها، وتجلس عليها، في التشهد الأول كذلك، في الأخير تتورك، تقعد على مقعدتها، وتخرج رجلها اليسرى من يمينها تحت رجلها اليمنى كالرجل سواء، هذا هو الصواب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10972/كيفية-جلوس-المراة-في-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41907.mp3","categories":["التشهد والتسليم"]},{"id":12939,"question":"السائلة تقول في سؤالها الأخير: إذا صليت صلاة العشاء، وجلست للتشهد الأول، ونسيت، وقرأت التشهدين، هل علي شيء؟","title":"حكم قراءة الصلاة الإبراهيمية في التشهد الأول","answer":"الجواب:  ليس عليك شيء، السنة إذا قرأت التشهد الأول أن تقومي إلى الثالثة بعد الصلاة على النبي ﷺ الأفضل أن تصلي على النبي ﷺ فإن قمت بعد قولك: أشهد أن لا إله إلا الله، وأشهد أن محمد عبده ورسوله؛ فلا بأس، وإن صليت على النبي ﷺ ثم قمت؛ فلا بأس، أما الدعاء التعوذ من عذاب جهنم، ومن عذاب القبر، وبقية الأدعية فتكون في الأخير. لكن لو أن إنسانًا أتى بها في الأول نسيانًا؛ فلا شيء عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11155/حكم-قراءة-الصلاة-الابراهيمية-في-التشهد-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_501/50114.mp3","categories":["التشهد والتسليم"]},{"id":13040,"question":"سؤاله الثاني يقول: هل يقول المصلي في أثناء التشهد: السلام عليك أيها النبي! أو يقول: السلام على النبي؟","title":"حكم قول المصلي في التشهد: السلام عليك أيها النبي","answer":"الجواب:  كلاهما جائز، والأفضل أن يقول: السلام عليك أيها النبي! ورحمة الله وبركاته؛ لأن هذا هو المحفوظ في الأحاديث الصحيحة عن رسول الله ﷺ أنه كان يعلم أصحابه هكذا، في حديث ابن مسعود، وفي حديث أبي مسعود الأنصاري وغيرهما يعلمهم: (السلام عليك أيها النبي) وهكذا في حديث أبي موسى وغيرهما، فهذا هو الأفضل: السلام عليك أيها النبي! ورحمة الله وبركاته . فإن قال: (السلام على النبي ورحمة الله وبركاته) صح، يروى هذا عن ابن مسعود  لكن الأول هو الذي ينبغي؛ لأنه هو الذي صدر من النبي ﷺ وعلمه أصحابه، السلام عليك أيها النبي! وهذا من باب الاستحضار، ما هو بدعاء للنبي ﷺ دعاء له، قد يتوهم بعض الناس أن هذا دعاء للنبي ﷺ وليس دعاء للنبي، ما يدعوه الإنسان إنما يدعو له، فهو يدعو له بالسلامة والرحمة والبركة السلام عليك أيها النبي يعني: السلامة من الله لك، والرحمة من الله لك والبركة، وليس يطلب من الرسول ﷺ السلامة بل يدعو له بالسلامة، يدعو له بالرحمة والبركة، فقوله: (أيها النبي) ليس دعاء له (يا أيها النبي) هو بمعناه أني أسأل النبي شيئًا، بل معناه: أخصك أيها النبي بهذه الدعوة (السلام عليك أيها النبي) يعني: أخصك أيها النبي بهذا الدعاء من السلامة والرحمة والبركة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11257/حكم-قول-المصلي-في-التشهد-السلام-عليك-ايها-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_473/47302.mp3","categories":["التشهد والتسليم"]},{"id":13196,"question":"يقول السائل عبدالرحمن إبراهيم عبدالرحمن من جنوب أفريقيا، يقول في سؤاله الثاني: في التشهد هل يقال: السلام على النبي، أم السلام عليك أيها النبي، وجهونا في ذلك؟","title":"الصيغة الصحيحة للسلام على النبي في التشهد","answer":"الجواب:  الأفضل أن يقال: السلام عليك أيها النبي ورحمة الله وبركاته، هذا الذي علمه النبي ﷺ أصحابه، وتوفي النبي ﷺ وهم يعملون ذلك، ولم يقل لهم إذا مت يقولوا: السلام على النبي، فدل ذلك على أنهم يقولون: السلام عليك أيها النبي -حيًا وميتًا- ومعنى (عليك أيها النبي) من باب الاستحضار، من باب استحضاره في الذهن والقلب، السلام عليك أيها النبي، ليس دعاء له، ولكنه دعاء له، يدعو له بالسلامة والرحمة والبركة، لا يطلب منه شيئًا، وإنما يدعو له بالسلامة والرحمة والبركة، فيقول: سلام الله عليك أيها النبي، يعني: أعطاك الله السلامة، وأعطاك الله الرحمة، وأعطاك الله البركة، هذا هو الأفضل. وجاء عن ابن مسعود  أنه كان يقول بعد النبي: السلام على النبي والأفضل ما صحت به الأخبار عن رسول الله ﷺ أنه كان يعلم أصحابه أن يقولوا: السلام عليك أيها النبي هذا هو الأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11464/الصيغة-الصحيحة-للسلام-على-النبي-في-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51203.mp3","categories":["التشهد والتسليم"]},{"id":13803,"question":"يسأل أخونا ويقول: هل السنة في الصلاة الثنائية الافتراش أو التورك؟","title":"ما السنة في الصلاة الثنائية التورك أم الافتراش؟","answer":"الجواب: السنة فيها الافتراش كالتشهد الأول هذا هو الأفضل، والتورك يكون في التشهد الأخير من الرباعية والثلاثية في المغرب والعشاء والظهر والعصر، كما جاء ذلك صريحًا في حديث أبي حميد الساعدي ، فالسنة للمؤمن في صلاته أن يفترش بين السجدتين وفي التشهد الأول ويتورك في التشهد الأخير. نعم.\nالمقدم: جزاكم الله خيرًا، أخونا زيل رسالته شيخ عبدالعزيز بقوله: أرجو من سماحة الشيخ أن يملي علينا رقم هاتفه. الشيخ: الهواتف كثيرة لكن منها: 4354444، الهاتف الثاني: 4351421. المقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/12188/ما-السنة-في-الصلاة-الثناىية-التورك-ام-الافتراش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60207.mp3","categories":["التشهد والتسليم"]},{"id":13810,"question":"يسأل أخونا ويقول: هل السنة في الصلاة الثنائية الافتراش أو التورك؟","title":"ما السنة في الصلاة الثنائية التورك أم الافتراش؟","answer":"الجواب: السنة فيها الافتراش كالتشهد الأول هذا هو الأفضل، والتورك يكون في التشهد الأخير من الرباعية والثلاثية في المغرب والعشاء والظهر والعصر، كما جاء ذلك صريحًا في حديث أبي حميد الساعدي ، فالسنة للمؤمن في صلاته أن يفترش بين السجدتين وفي التشهد الأول ويتورك في التشهد الأخير. نعم.\nالمقدم: جزاكم الله خيرًا، أخونا زيل رسالته شيخ عبدالعزيز بقوله: أرجو من سماحة الشيخ أن يملي علينا رقم هاتفه. الشيخ: الهواتف كثيرة لكن منها: 4354444، الهاتف الثاني: 4351421. المقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/12188/ما-السنة-في-الصلاة-الثناىية-التورك-ام-الافتراش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60207.mp3","categories":["التشهد والتسليم"]},{"id":13856,"question":"هل يجوز لي أن أتورك في الصلاة الثنائية كصلاة الفجر والنوافل؟ أم أنها سنة في الصلاة الرباعية والثلاثية؟","title":"هل يتورك في الصلاة الثنائية؟","answer":"الجواب: التورك سنة في الرباعية والثلاثية أما الثنائية كالجمعة والفجر والنوافل السنة فيها الافتراش هذا هو الأفضل. نعم.\nالمقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/12232/هل-يتورك-في-الصلاة-الثناىية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53726.mp3","categories":["التشهد والتسليم"]},{"id":13857,"question":"السائل سعد أحمد يقول في هذا  كيف كان هدي النبي ﷺ في رفع السبابة وتحريكها في الصلاة؟ وجزاكم الله خيرًا.","title":"هدي النبي ﷺ في وضعية السبابة في الصلاة","answer":"الجواب: كان النبي ﷺ يشير بها من حين يجلس للتشهد، يشير بالسبابة غير قائمة محنية قليلًا، كما روى النسائي أن النبي ﷺ كان يفعل ذلك، فهو يشير بها من حين يجلس إلى أن يسلم وهي غير منتصبة كثيرة بل محنية قليلًا ويحركها عند الدعاء عليه الصلاة والسلام، ويجعل نظره إليها وقت الجلوس، لا يتجاوز بصره سبابته عليه الصلاة والسلام، هذا هو السنة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12227/هدي-النبي-ﷺ-في-وضعية-السبابة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53723.mp3","categories":["التشهد والتسليم"]},{"id":14309,"question":"ما قولكم فيمن يقول في التشهد: التحيات المباركات والصلوات والطيبات لله، هل في هذا بدعة؟","title":"حكم التشهد بقول «التحيات المباركات..»","answer":"الجواب: هذا مشروع ليس فيه بدعة، هذا ثبت عن النبي ﷺ من حديث ابن عباس رضي الله عنهما أن النبي ﷺ علمهم التشهد أن يقولوا هكذا: التحيات المباركات الصلوات الطيبات لله هذا نوع من أنواع التشهد، والتشهد جاء على أنواع عن النبي ﷺ هذا نوع منها، والنوع الثاني ما جاء في حديث ابن مسعود: التحيات لله والصلوات والطيبات ما فيها ذكر المباركات السلام عليك أيها النبي.. إلى آخره، فالأمر واسع والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12789/حكم-التشهد-بقول-التحيات-المباركات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62205.mp3","categories":["التشهد والتسليم"]},{"id":14447,"question":"هذه السائلة أم ماجد من الدمام تقول في هذا  سماحة الشيخ، هذا الدعاء: اللهم أعني على ذكرك وشكرك، وحسن عبادتك هل يقال قبل السلام أم بعد السلام؟","title":"أفضلية الدعاء قبل السلام في الصلاة","answer":"الجواب: الأفضل قبل السلام، هذا الأفضل؛ لأن الدعاء قبل السلام أفضل؛ لقوله ﷺ لما علمهم التحيات قال: ثم ليختر من المسألة ما شاء وفي اللفظ الآخر: ثم ليختر من الدعاء أعجبه إليه فيدعو فإذا دعا بهذا قبل السلام فهو أفضل، وإن دعا به بعد السلام أو بعد الذكر فلا بأس، لكن قبل السلام أفضل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12914/افضلية-الدعاء-قبل-السلام-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55405.mp3","categories":["الأدعية والأذكار","التشهد والتسليم"]},{"id":14593,"question":"هناك بعض الناس إذا بدأ قراءة التشهد يبدؤها بقوله: الحمد لله، هل ورد في هذا شيء؟","title":"حكم بدأ التشهد بالحمد لله","answer":"الجواب: لا، ليس بمشروع، يبدؤها بقوله: (التحيات) هذا المشروع، المحفوظ عن النبي ﷺ أنه علمهم أن يقولوا: التحيات لله... هذا أول التشهد، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13090/حكم-بدا-التشهد-بالحمد-لله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_635/nour_635013.mp3","categories":["التشهد والتسليم","البدع والمحدثات"]},{"id":14678,"question":"تسأل أختنا وتقول: قرأت صيغًا مختلفة للتشهد أيها أصح؟لو تكرمتم.","title":"أصح صيغ التشهد","answer":"الجواب: أصحها ما ثبت في حديث ابن مسعود  في الصحيحين: أن النبي ﷺ علم الصحابة أن يقولوا في التشهد في نهاية الصلاة: التحيات لله، والصلوات والطيبات، السلام عليك أيها النبي ورحمة الله وبركاته، السلام علينا وعلى عباد الله الصالحين، أشهد أن لا إله إلا الله، وأشهد أن محمدًا عبده ورسوله هذا هو أصح ما ورد في ذلك، ثم يشرع لهم بعد هذا أن يصلي على النبي ﷺ، يقول: اللهم صل على محمد وعلى آل محمد، كما صليت على إبراهيم وعلى آل إبراهيم؛ إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم ؛ إنك حميد مجيد. ثم يشرع له التعوذ من أربع يقول: أعوذ بالله من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال. ثم يدعو بما حب من خير الدنيا والآخرة، ويسأل الله خير الدنيا والآخرة، وإذا تشهد بأنواع أخرى مما صح عن النبي ﷺ فلا بأس، كله طيب، وكله مجزي. ومنها حديث ابن عباس عند مسلم في الصحيح: التحيات المباركات الصلوات الطيبات لله... إلى آخره، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13186/اصح-صيغ-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_628/nour_62808.mp3","categories":["التشهد والتسليم"]},{"id":15029,"question":"عند الجلوس للتشهد أريد توضيح تحريك السبابة، هل هو عند بداية التشهد أم بعد نهاية التشهد عند الدعاء فقط؟","title":"متى يكون تحريك السبابة في التشهد؟","answer":"الجواب: السنة أن يشير بالسبابة، يقيم السبابة من أول الجلوس في التحيات، التشهد الأول والأخير.  أما التحريك فالسنة أن يكون عند الدعاء، عند: اللهم صلّ، اللهم إنا نعوذ بك من عذاب جهنم، عند الدعاء، يحركها قليلًا عند الدعاء.  أما كونها قائمة هذا من حين يجلس تكون قائمة إشارة إلى التوحيد، ويعقد إبهامه مع الوسطى، ويقبض الخنصر والبنصر، أو يقبض أصابعه كلها، ويشير بالسبابة هذا سنة، لكن التحريك يكون عند الدعاء، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13521/متى-يكون-تحريك-السبابة-في-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56306.mp3","categories":["التشهد والتسليم"]},{"id":15387,"question":"سؤاله الثاني يقول: إذا فرغ المصلي من صلاته، وأراد أن يسلم، فهل يقول: (السلام عليكم ورحمة الله وبركاته) يمينًا ثم يسارًا، أم يقول: (السلام عليكم ورحمة الله) فقط؟ وما حكم صلاة من فعل ذلك بزيادة (وبركاته)؟","title":"حكم زيادة (وبركاته) في السلام من الصلاة","answer":"الجواب: المحفوظ في السنة (ورحمة الله) فقط، وهذا هو المشروع أن يقول: (السلام عليكم ورحمة الله) عن يمينه وشماله، أما زيادة: (بركاته) ففيها خلاف بين أهل العلم، وقد روى علقمة بن وائل عن أبيه أن النبي ﷺ قال هكذا: السلام عليكم ورحمة الله وبركاته لكن في رواية علقمة عن أبيه خلاف، من أهل العلم من صحح سماعه منه، ومنهم من قال: إنها منقطعة. فينبغي للمؤمن ألا يزيدها، والأولى والأفضل أن يقتصر على: (ورحمة الله) ومن زادها ظانًا صحتها أو جاهلًا بالموضوع فلا حرج، صلاته صحيحة، لكن الأولى والأحوط أن لا يزيدها خروجًا من خلاف العلماء، وعملًا بالأمر الأثبت والأقوى، نعم.","link":"https://binbaz.org.sa/fatwas/13894/حكم-زيادة-وبركاته-في-السلام-من-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_684/nour_68404.mp3","categories":["التشهد والتسليم"]},{"id":15487,"question":"وهذه أولى رسائل هذا اللقاء، وردت من المستمع: أحمد سليمان عمر، من إريتريا، له عدة أسئلة، في سؤاله الأول يقول: هل الصلاة المفروضة أو الدعاء إذا لم يذكر فيها الصلاة على النبي ﷺ تكون صحيحة أم لا؟ فإن أحد الأشخاص قال لنا: إن الصلاة والدعاء لا تقبل إذا لم يذكر فيهما الصلاة على النبي ﷺ؟ أفيدونا عن ذلك، أفادكم الله.","title":"حكم الصلاة على النبي ﷺ في الدعاء والصلاة","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فإن الصلاة على النبي ﷺ مشروعة في صلاتنا، في الظهر، والعصر، والمغرب، والعشاء، والفجر وفي جميع النوافل، يشرع للمصلي أن يصلي على النبي ﷺ في التحيات -في آخر الصلاة- بعدما يقول: أشهد أن لا إله إلا الله، وأشهد أن محمدًا عبده ورسوله، يقول: اللهم صل على محمد، وعلى آل محمد، كما صليت على إبراهيم، وعلى آل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد هذا نوع من الصلاة الإبراهيمية الثابتة عن النبي ﷺ، وهناك أنواع أخرى، منها:\nقوله: اللهم صل على محمد وعلى آل محمد كما صليت على آل إبراهيم، وبارك على محمد وعلى آل محمد كما باركت على آل إبراهيم في العالمين إنك حميد مجيد.\nونوع ثالث: اللهم صل على محمد وعلى أزواجه وذريته، كما صليت على آل إبراهيم، وبارك على محمد وعلى أزواجه، وذريته كما باركت على آل إبراهيم إنك حميد مجيد.\nوهناك أنواع أخرى من الصلاة على النبي ﷺ، وإذا أتى المسلم المصلي أو المرأة بنوع منها مما ثبت عن رسول الله ﷺ صح وكفى، ثم بعد هذا يقول: اللهم إني أعوذ بك من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال ويدعو بما أحب من الدعوات الطيبة قبل أن يسلم. وهذه الصلاة تشرع أيضًا في التشهد الأول على الصحيح، وقال جمع من أهل العلم: إنها لا تقال إلا في التشهد الأخير، ولكن الصحيح: أنه يؤتى بها أيضًا في التشهد الأول بعد الثنتين الظهر والعصر والمغرب والعشاء، إذا جلس في الثانية، وقال: أشهد أن لا إله إلا الله، وأشهد أن محمدًا عبده ورسوله، يصلي على النبي ﷺ ثم ينهض إلى الثالثة.  أما بقية الدعاء، في الأخير، في التشهد الأخير، وهذا القول أصح، فعلى هذا: نصلي على النبي ﷺ في صلاتنا مرتين في الظهر، والعصر، والمغرب، والعشاء مرتين في التشهد الأول وفي التشهد الأخير، هذا هو الأفضل. واختلف العلماء: هل هي فريضة وركن في التشهد الأخير أم لا؟ على أقوال:\nمنهم من قال: إنها ركن لا بد منها، ولا تصح الصلاة إلا بها، وهذا هو المعروف في مذهب أحمد بن حنبل وجماعة.\nوقال آخرون: بل هي واجبة لا ركن، بل واجبة، إن تعمد تركها بطلت الصلاة، وإن نسيها لم تبطل الصلاة، ولكن يسجد للسهو، وهذا قول وسط.\nوقال آخرون: إنها سنة، لا تبطل الصلاة بتركها لا عمدًا ولا سهوًا، بل هي سنة مؤكدة؛ لأن الرسول ﷺ لم يفرضها على الناس، ولكن لما سألوه قالوا: «كيف نصلي عليك؟ قال: قولوا: اللهم صل على.... إلى آخره» ولو كانت فرضًا لفرضها عليهم قبل أن يسألوه، وبيّنها لهم مع التشهد. وبكل حال فالذي ينبغي هو المجيء بها؛ لأن الرسول أمر بها -عليه الصلاة والسلام- وقال: قولوا اللهم صل... إلى آخره، وهذا أمر، والأمر يقتضي الوجوب، فلا ينبغي للمؤمن أن يدعها في التشهد الأخير.\nأما التشهد الأول فالأمر فيه واسع، إن أتى بها فهو أفضل، وإن لم يأت بها فلا حرج عليه، ولكن ليست شرطًا للقبول إذا قلنا بها في التشهد الأول، إنما هي مستحبة.  أما في التشهد الأخير فقد سمعت الخلاف، بعض أهل العلم قال: إنها لا بد منها، وأنه إذا تعمدها بطلت الصلاة، كما لو تعمد ترك التشهد، أو تعمد ترك الركوع أو السجود تبطل الصلاة، وقال آخرون من أهل العلم: إنها لا تبطل الصلاة بذلك، ولكن يستحب له أن يصلي على النبي ﷺ في آخر الصلاة، فإن ترك لم تبطل صلاته، في أقوال أهل العلم المعروفة.  فلا ينبغي للمؤمن أن يدعها، بل ينبغي له أن يحافظ عليها، ويجتهد في فعلها بعد التحيات، وبعد قوله: أشهد أن لا إله إلا الله، وأشهد أن محمدًا عبده ورسوله، قبل أن يسلم، يصلي على النبي ﷺ حتى تصح صلاته عند الجميع، وحتى لا يعرضها للبطلان. وأما الدعاء فهي مستحبة في الدعاء، لكن ليست شرطًا في القبول، لو دعا ولم يصل على النبي ﷺ يرجى قبول دعائه، ولكن الأفضل أن يصلي على النبي ﷺ قبل الدعاء وبعد الدعاء، هذا هو الأفضل؛ لأن الرسول ﷺ: لما رأى رجلًا دعا ولم يحمد الله، ولم يصل على النبي ﷺ قال: عجل هذا ثم قال: إذا دعا أحدكم فليبدأ بتمجيد ربه والثناء عليه، ثم ليصل على النبي ﷺ، ثم يدعو بما شاء.\nفأرشدنا إلى أن نحمد الله أولًا، ثم نصلي على النبي ﷺ، ثم ندعو، وهذا هو الأفضل، وهذا هو الأقرب إلى الإجابة، لكنه ليس شرطًا، وإذا ختم الدعاء بالصلاة على النبي ﷺ كان أيضًا أفضل وأكمل، وهو من أسباب الإجابة، لكن لو ترك لا يقال: لا يجاب الدعاء، بل الدعاء قد يجاب، قد يحصل به المقصود، ولو لم يحمد الله في أوله، ولو لم يصل على النبي ﷺ في أوله ولا في آخره؛ لكن فعل ذلك يعني: كونه يحمد الله أولًا، ويصلي على النبي ﷺ، ثم يدعو ويلح بالدعاء، ثم يختم بالصلاة...، هذا كله من باب السنن، من باب الفضائل، وهو من أسباب الإجابة، ولكن ليس شرطًا للقبول، فلو دعا ولم يصل على النبي ﷺ لم يكن آثمًا، ولا يرد دعاؤه، بل يرجى قبوله إذا أخلص في ذلك، وسلم من الموانع التي تمنع من الإجابة، والموانع كثيرة، فالمعاصي من أسباب الموانع، من أسباب عدم الإجابة، وأكل الحرام من أسباب عدم الإجابة، والغفلة عن الله كونه يدعو بقلب ساهٍ غافل من أسباب عدم الإجابة. فعدم الإجابة له أسباب، فينبغي للمؤمن أن يحرص على أسباب الإجابة، بأن يكون طعامه حلالًا، وأن يكون بعيدًا عن المعاصي عما حرم الله، ويدعو الله بقلب حاضر، مشفق راغب راجي، يرجو ربه ويخافه، قد حضر بين يديه ، ويتحرى أوقات الإجابة كآخر الليل، وآخر الصلاة قبل السلام والسجود؛ لأن الدعاء في السجود حري بالإجابة أيضًا، وهكذا بين الأذان والإقامة، من أسباب الإجابة، نسأل الله للجميع التوفيق، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/14016/حكم-الصلاة-على-النبي-ﷺ-في-الدعاء-والصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_690/nour_69001.mp3","categories":["الأدعية والأذكار","التشهد والتسليم"]},{"id":15614,"question":"هل رفع السبابة في التشهد سنة أم بدعة؟ وما الدليل على ذلك؟مأجورين.","title":"حكم الإشارة بالسبابة في التشهد","answer":"الجواب: السنة الإشارة في التشهد، كما كان النبي يفعل ﷺ، كان يشير بالسبابة في الأحاديث الصحيحة في تشهده الأول والأخير، يشير بها للوحدانية -عليه الصلاة والسلام-، ويقبض الأصابع كلها، ويشير بالسبابة في التشهد الأول والأخير، ولا تزال منصوبة إلى سلامه من التشهد الأخير -عليه الصلاة والسلام-، وربما حلق الإبهام والوسطى وقبض الخنصر والبنصر وأشار بالسبابة تارةً يقبض أصابعه كلها، ويشير بالسبابة، وتارةً يحلق الإبهام مع الوسطى ويقبض الخنصر والبنصر ويشير بالسبابة، هذا هو السنة إشارة للوحدانية، ويضع يده اليمنى على فخذه اليمنى، واليسرى على اليسرى حال جلوسه للتشهد، وربما وضع يديه على الركبتين، وكان بين السجدتين يضعهما على الركبتين، وربما وضعهما على الفخذين بين السجدتين، وفي التشهد يضع اليسرى على فخذه اليسرى، أو على ركبته اليسرى، واليمنى على فخذه اليمنى، ويحلق إبهامها مع الوسطى، ويشير بالسبابة، وربما قبض الأصابع كلها وأشار بالسبابة حال تشهده -عليه الصلاة والسلام-، نعم.","link":"https://binbaz.org.sa/fatwas/14154/حكم-الاشارة-بالسبابة-في-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57102.mp3","categories":["التشهد والتسليم"]},{"id":15727,"question":"تسأل أختنا فتقول: هل نقرأ في السنة كالتراويح مثلًا التشهد الأخير فقط، أو نقرأ التشهد الأول والأخير؟","title":"هل يُقرأ التشهد كاملًا قبل السلام في النفل؟","answer":"الجواب: التشهد الأول والأخير جميعًا في كل ركعتين، التراويح والنوافل يقرأ التشهد، ويصلي على النبي ﷺ، ويتعوذ بالله من الأربع: من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال، ويسأل ربه ما تيسر من الدعوات الطيبة، يستعيذ بالله مما أحب، محل دعاء، التحيات محل دعاء، إذا فرغ من التشهد والصلاة على النبي ﷺ محل دعاء في الفرض والنفل، وإذا دعا فهو أفضل، فيجتهد في الدعاء، كان النبي ﷺ يدعو، ويحث الناس على الدعاء، يقول: ثم ليختر من الدعاء أعجبه إليه فيدعو به هذا سنة مشروعة في الفرائض والنوافل قبل أن يسلم، وفي السجود أيضًا يشرع الدعاء في السجود، نعم.","link":"https://binbaz.org.sa/fatwas/14291/هل-يقرا-التشهد-كاملا-قبل-السلام-في-النفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70614.mp3","categories":["التشهد والتسليم"]},{"id":15773,"question":"يقول عن نفسه: كنتُ في الماضي أقرأ التشهد كله في التشهد الأول، فهل ما كنت أفعله صحيح؟","title":"حكم قراءة التشهد كاملًا في التشهد الأول","answer":"الجواب: لا حرج في ذلك من جهة الإثم، ولكن السنة أن تقف عند نهاية الصلاة على النبي ﷺ، الدعاء يبقى في التشهد الأخير، هذا هو السنة بعد الفراغ من الصلاة على النبي ﷺ تقوم إلى الثالثة، هذا هو المشروع، كان النبي ﷺ إذا فرغ من هذا قام، وكان يدعو في التشهد الأخير، ويتعوذ بالله من عذاب جهنم، إلى آخره.  فأنت عليك أن تقتدي بالنبي ﷺ فيكون الدعاء في التشهد الأخير، أما التشهد الأول ينتهي عند الصلاة على النبي ﷺ، إذا صليت على النبي ﷺ تقوم إلى الثالثة، ولكن ما مضى لا حرج عليك فيه؛ لأنك جبت دعوات في غير محلها، فلا تبطل الصلاة، ولكنك خالفت المشروع، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14357/حكم-قراءة-التشهد-كاملا-في-التشهد-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74111.mp3","categories":["التشهد والتسليم"]},{"id":15968,"question":"من القصيم بريدة رسالة بعثت بها إحدى الأخوات المستمعات، تقول: أختكم في الله أم هدى عبد الهادي، أختنا لها جمع من الأسئلة في أحدها تسأل عن سبب نزول التشهد في الصلاة؟ وهل الله تعالى كلم به رسوله -عليه الصلاة والسلام-؟","title":"سبب وجوب التشهد في الصلاة","answer":"الجواب: الرسول ﷺ علم أمته التشهد في الصلاة، هو لا ينطق عن الهوى، قال الله : وَالنَّجْمِ إِذَا هَوَى ۝ مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَى ۝ وَمَا يَنْطِقُ عَنِ الْهَوَى ۝ إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى [النجم:1-4]. فجميع السنة كلها من وحي الله إلى نبيه ﷺ، وهو المبلغ عن الله، الرسول ﷺ يبلغ عن الله أحكام الشرع كما بلغ عنه القرآن الذي هو كلام الله، هكذا بلغ عنه السنة فيما يتعلق، بالصلاة والزكاة والصيام والحج وغير ذلك، يبلغ عن الله أحكام دينه -عليه الصلاة والسلام-، فالتشهد من جملة ذلك، علم الأمة التشهد الأول، والتشهد الأخير -عليه الصلاة والسلام-، وعلمهم ما يقولون في التشهد الأخير من التعوذ من عذاب جهنم، ومن عذاب القبر، ومن عذاب النار، ومن فتنة المسيح الدجال، وعلمهم دعوات كثيرة -عليه الصلاة والسلام-، كان يقول في سجوده: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره. وعلم الصديق لما قال الصديق: يا رسول الله الصديق أبو بكر قال: يا رسول الله علمني دعاءً أدعو به في صلاتي، قال: قل: اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت؛ فاغفر لي مغفرة من عندك، وارحمني إنك أنت الغفور الرحيم. وقالت عائشة: يا رسول الله، إن وافقت ليلة القدر ما أقول فيها؟ قال: قولي: اللهم إنك عفو، تحب العفو، فاعف عني فالرسول ﷺ يبلغ الناس ما أمره الله، وما شرعه الله في الصلاة وغيرها، في التشهد وغيره، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14574/سبب-وجوب-التشهد-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_710/nour_71014.mp3","categories":["التشهد والتسليم"]},{"id":16092,"question":"يقول -يا سماحة الشيخ- هذا السائل أبو معاذ من الرياض: يقوم بعض الناس بين التسليمة الأولى، والتسليمة الثانية بهز رأسه إلى أسفل، فما الحكم في ذلك؟","title":"حكم هز المصلي رأسه إلى الأسفل بين التسليمتين","answer":"الجواب: ما له أصل ... الأصل تركه، يكره هذا، ما له أصل، ليس له أصل. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14732/حكم-هز-المصلي-راسه-الى-الاسفل-بين-التسليمتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57912.mp3","categories":["التشهد والتسليم"]},{"id":16151,"question":"يقول: أنا لا أقرأ، ولا أكتب، وكثيرًا ما أخطئ في التحيات، اقرؤوها لي لعلني أحفظها من هذا الجهاز، جزاكم الله خيرًا.","title":"صيغة التشهد في الصلاة","answer":"الجواب: الرسول ﷺ علمها أصحابه وهي: التحيات لله، والصلوات والطيبات، السلام عليك أيها النبي، ورحمة الله وبركاته، السلام علينا، وعلى عباد الله الصالحين، أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده ورسوله نعيدها، ولعلك تكتبها. المقدم: يبدو أنه لا يقرأ ولا يكتب. الشيخ: التحيات لله، والصلوات والطيبات، السلام عليك أيها النبي، ورحمة الله وبركاته، السلام علينا وعلى عباد الله الصالحين، أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده ورسوله هذا في التشهد الأول والثاني. التحيات في الجلوس الأول بعد الثانية، وفي الثالثة في المغرب، وفي الرابعة في الظهر والعصر والعشاء، ثم تقول بعدها في التشهد الأخير في الثالثة من المغرب، والرابعة من الظهر والعصر والعشاء، وفي صلاة الفجر، والجمعة، والعيدين، والاستسقاء، تقول بعد هذا: اللهم صل على محمد وعلى آل محمد، كما صليت على إبراهيم، وعلى آل إبراهيم، إنك حميد مجيد، اللهم بارك على محمد، وعلى آل محمد، كما باركت على إبراهيم، وعلى آل إبراهيم، إنك حميد مجيد. وإذا فعلت هذا أيضًا في التشهد الأول؛ فهو أيضًا مشروع، ومستحب، يعني في التشهد الذي بعد الثانية في الظهر والعصر والمغرب والعشاء، إذا صليت على النبي ﷺ كما ذكر فهو طيب ومشروع؛ لعموم الأحاديث في ذلك، فإن الصحابة سألوا النبي ﷺ قالوا: «يا رسول الله! أمرنا الله أن نصلي عليك، فكيف نصلي عليك؟ يعني في قوله تعالى: إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا [الأحزاب:56] -اللهم صل عليه وسلم-  سألوه؛ قالوا: يا رسول الله! كيف نصلي عليك؟ قال: قولوا: اللهم صل على محمد، وعلى آل محمد، كما صليت على إبراهيم، وعلى آل إبراهيم، إنك حميد مجيد، اللهم بارك على محمد، وعلى آل محمد، كما باركت على إبراهيم، وعلى آل إبراهيم، إنك حميد مجيد هذه الصيغة أكمل الصيغ التي وردت، وأتمها. وقد وردت في ألفاظ أخرى أخصر من هذا، وكلها صحيحة إذا أتى بواحد منها المؤمن، أو المؤمنة؛ كفى، ومنها: اللهم صل على محمد، وعلى آل محمد، كما صليت على آل إبراهيم، وبارك على محمد، وعلى آل محمد، كما باركت على آل إبراهيم، في العالمين إنك حميد مجيد هذه صيغة. صيغة ثالثة: اللهم صل على محمد، وعلى أزواجه، وذريته، كما صليت على آل إبراهيم، وبارك على محمد، وعلى أزواجه، وذريته، كما باركت على إبراهيم، وعلى آل إبراهيم، إنك حميد مجيد. الصيغة الرابعة: اللهم صل على محمد عبدك ورسولك، كما صليت على إبراهيم، وبارك على محمد، وعلى آل محمد كما باركت على إبراهيم، وعلى آل إبراهيم، إنك حميد مجيد. إذا أتى المؤمن، أو المؤمنة بواحدة من هذه الصيغات الصحيحة كله طيب، وأكملها الأولى، أكملها وأتمها الأولى، اللهم صل على محمد، وعلى آل محمد، كما صليت على إبراهيم، وعلى آل إبراهيم، إنك حميد مجيد، اللهم بارك على محمد، وعلى آل محمد، كما باركت على إبراهيم، وعلى آل إبراهيم، إنك حميد مجيد في التشهد الأول والثاني، لكن في الثاني يتعين عند جمع من أهل العلم، الصلاة على النبي ﷺ في الثاني في التشهد الأخير متعينة عند جمع من أهل العلم. فينبغي ألا تدعها، وأن تحافظ عليها، ثم تقول بعد هذا كله في التشهد الأخير الذي بعده السلام، تقول بعد ذلك: اللهم إني أعوذ بك من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال. نعيده: اللهم إني أعوذ بك من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال في آخر الصلاة، قبل السلام، ويستحب الزيادة على هذا: اللهم أعني على ذكرك، وشكرك، وحسن عبادتك؛ لأن الرسول أوصى بذلك -عليه الصلاة والسلام- اللهم أعني على ذكرك وشكرك، وحسن عبادتك قبل السلام.  دعاء آخر قبل السلام: اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك، وارحمني، إنك أنت الغفور الرحيم نعيدها: اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك، وارحمني، إنك أنت الغفور الرحيم. النبي ﷺ أوصى أبا بكر بهذا الدعاء، وأوصى معاذًا بالدعاء الذي قبلة اللهم أعني على ذكرك... وهي وصية للجميع -لجميع المسلمين- وصيته لواحد، وصية للجميع -عليه الصلاة والسلام- وكلها سنة، ليست واجبة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14814/صيغة-التشهد-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_750/nour_75004.mp3","categories":["التشهد والتسليم"]},{"id":16437,"question":"سماحة الشيخ! في آخر أسئلة هذا السائل فضل الله من السودان مقيم في ليبيا يقول: رجل إذا سلم عن يمينه يقول: السلام عليكم ورحمة الله، اللهم إني أسألك الفوز بالجنة، وإذا سلم عن شماله قال: السلام عليكم ورحمة الله، اللهم إني أسألك النجاة من النار، فهل هذا مكروه، أم لا؟ فإن كان مكروهًا فما الدليل على كراهته؟ مأجورين.","title":"حكم إضافة أدعية بعد كل تسلمية في الصلاة","answer":"الجواب: ليس لهذا أصل، بل هذا بدعة، لا يقول شيء إذا سلم إلا ما قاله النبي ﷺ إذا سلم التسليمتين يقول: أستغفر الله، أستغفر الله، أستغفر الله، اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال والإكرام هكذا كان النبي ﷺ يفعل إذا سلم، أما هذا الدعاء بعد التسليمة الأولى، والتسليمة الثانية هذا لا أصل له، هذا من كيسه، بدعة، نعم. المقدم: زيادة السلام عليكم ورحمة الله وبركاته في السلام يا شيخ؟ الشيخ: الأفضل عدمها؛ لأن في صحتها نظر، وخلاف بين أهل العلم، والمحفوظ: السلام عليكم ورحمة الله. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15133/حكم-اضافة-ادعية-بعد-كل-تسلمية-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58129.mp3","categories":["التشهد والتسليم","البدع والمحدثات"]},{"id":16543,"question":"أيضًا من زاد على التشهد الأول في الركعتين الأوليين هل عليه سجود سهو؟","title":"حكم الصلاة على النبي ﷺ في التشهد الأول","answer":"الجواب: لا، إذا زاد الصلاة على النبي ﷺ مستحب، أن يصلي على النبي ﷺ في التشهد الأول، من زاد الدعاء بعد الصلاة على النبي ﷺ فالأمر في هذا واسع، لا يلزمه السجود؛ لأن هذه الزيادة لا تبطل الصلاة، إنما قصاراها أنها غير مشروعة، ولو سجد للسهو لا يضر، لو أتى بشيء ما هو بمشروع في الصلاة، وسجد للسهو؛ لا يضره؛ لأن القاعدة: أن سجود السهو إنما يجب إذا أتى بشيء يبطل عمده الصلاة، إذا أتى بشيء في الصلاة يبطل عمده الصلاة سهوًا؛ وجب عليه سجود السهو، أما إذا كان الشيء لا يبطل عمده الصلاة؛ بأن أتى بشيء مخصوص؛ لا يبطلها، أو جاء بشيء غير مشروع؛ لا يبطلها، هذا لا يلزمه سجود السهو ... نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15271/حكم-الصلاة-على-النبي-ﷺ-في-التشهد-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_815/nour_81504.mp3","categories":["التشهد والتسليم"]},{"id":17054,"question":"هذا سائل يقول: من نسي التشهد الأوسط، فهل يجلس للتشهد الأخير متوركًا، أم مفترشًا؟ وكيف تصلى الأربع ركعات قبل الظهر؛ هل بسلام واحد، أم بسلامين؟","title":"السنة التورك في التشهد الأخير والتسليم في النافلة من ركعتين","answer":"الجواب: السنة في التشهد الأول الافتراش، فإذا نسيه، وقام؛ سجد للسهو سجدتين، أما التورك فهو في التشهد الأخير، السنة أن يتورك في التشهد الأخير، وإن كان قد نسي التشهد الأول، السنة التورك في التشهد الأخير.  والتورك: أن يجلس على مقعدته، يخرج رجله اليسرى من جهة يمينه تحت رجله اليمنى، هذا هو التورك. والافتراش: أن يجلس على رجله اليسرى، وينصب اليمنى، وهذا مشروع في التشهد الأول، وبين السجدتين لمن قدر عليه.  أما في التشهد الأخير في المغرب، والعشاء، والظهر، والعصر فيتورك، يجلس على مقعدته تأسيًا بالنبي، عليه الصلاة والسلام. نعم. المقدم: تصلى الأربع ركعات قبل الظهر بسلام واحد؟ الجواب: السنة بسلامين في الظهر، وغيرها، يقول النبي ﷺ: صلاة الليل والنهار مثنى مثنى فيصلي أربعًا قبل الظهر بتسليمتين، وأربعًا قبل العصر بتسليمتين، هذا هو السنة، وأربعًا بعد الظهر بتسليمتين، هذا هو الأفضل. نعم.","link":"https://binbaz.org.sa/fatwas/15845/السنة-التورك-في-التشهد-الاخير-والتسليم-في-النافلة-من-ركعتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58730.mp3","categories":["التشهد والتسليم"]},{"id":17126,"question":"من أسئلة هذا السائل يقول يا سماحة الشيخ: هل تحريك الأصبع عند التشهد يجوز، أم لا؟ وخصوصًا عند التشهد الأول، وقال رسول الله ﷺ: \"ثلاث حركات تبطل الصلاة\" هل هذا حديث؟","title":"حكم تحريك الأصبع أثناء التشهد والحركة في الصلاة","answer":"الجواب: ليس بحديث: ثلاث حركات تبطل الصلاة ليس بحديث، بل من كلام بعض العلماء. والسنة الإشارة بالسبابة في التشهد، من حين يجلس للتشهد يشير بالسبابة إلى الوحدانية، إلى أن الله واحد، ويحركها عند الدعاء، ويحركها قليلًا عند الدعاء، عند: اللهم صل على محمد، وعند الدعاء يحركها قليلًا، ويكون ناصبًا لها من حين يجلس للتشهد إلى أن يسلم، إشارةً للتوحيد.","link":"https://binbaz.org.sa/fatwas/15942/حكم-تحريك-الاصبع-اثناء-التشهد-والحركة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58920.mp3","categories":["التشهد والتسليم"]},{"id":17245,"question":"هذه أختكم في الله أم أمل من ينبع، تقول في سؤالها الأول: متى تقول هذه الأدعية التالية يا سماحة الشيخ: اللهم إني أعوذ بك من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا، وفتنة الممات، ومن فتنة المسيح الدجال هل تقال هذه الأدعية في الفرائض؟ أم في الرواتب، بعد الفراغ من التشهد، وقبل السلام؟","title":"متى يقال: \"اللهم إني أعوذ بك من عذاب جهنم...\"؟","answer":"الجواب: في كل صلاة تقال هذه، قبل السلام، إذا تشهد، وصلى على النبي؛ يأتي بهذا الدعاء، كما علمه النبي أصحابه: إذا تشهد أحدكم، التشهد الأخير، فليقل: اللهم إني أعوذ بك من عذاب جهنم .. إلى آخره، فإذا تشهد، وصلى على النبي ﷺ يأتي بهذا الدعاء، وبقية الأدعية، يأتي بها قبل أن يسلم، هذا الدعاء وغيره، مثل: ربنا آتنا في الدنيا حسنة، وفي الآخرة حسنة، وقنا عذاب النار اللهم اغفر لي ولوالدي، اللهم أجرني من النار، اللهم أعني على ذكرك، وشكرك، وحسن عبادتك.. اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرةً من عندك، وارحمني، إنك أنت الغفور الرحيم.. اللهم أصلح قلبي وعملي.. أو اللهم اغفر لي ذنبي كله.. إلى غير هذا، كله قبل السلام، وبعد الصلاة على النبي ﷺ. نعم.","link":"https://binbaz.org.sa/fatwas/16077/متى-يقال-اللهم-اني-اعوذ-بك-من-عذاب-جهنم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59122.mp3","categories":["الأدعية والأذكار","التشهد والتسليم"]},{"id":17711,"question":"من ضمن أسئلة هذه السائلة أم مريم تقول: يرد كثير من الأحاديث: دبر كل صلاة فهل المقصود بها بعد انقضاء الصلاة أم قبل السلام؟","title":"المقصود بدبر الصلاة","answer":"الجواب: دبر الصلاة آخرها قبل السلام، هذا هو الأصل مثل دبر الحيوان مؤخره، فدبر الصلاة ما كان قبل السلام؛ آخرها قبل السلام يستحب فيه الدعاء بعد قراءة التحيات والصلاة على النبي ﷺ والتعوذ بالله من عذاب جهنم ومن عذاب القبر ومن فتنة المحيا والممات ومن فتنة المسيح الدجال، يستحب أن يدعو بعد هذا قبل أن يسلم في الفرض والنفل، وإن دعا بعد الذكر بعد السلام بعد العشاء فلا بأس بينه وبين نفسه، لكن الأفضل أن يكون الدعاء قبل السلام وبعد قراءة التحيات والصلاة على النبي ﷺ وبعد التعوذ بالله من عذاب جهنم ومن عذاب القبر ومن فتنة المحيا والممات ومن فتنة المسيح الدجال ؛ لأن الدبر؛ دبر الشيء آخره، ودبر الصلاة آخرها قبل السلام كما في الحديث أنه قال لمعاذ: لا تدعن دبر كل صلاة أن تقول: اللهم أعني على ذكرك وشكرك وحسن عبادتك هذا قبل السلام. وأما الحديث الآخر: كان النبي ﷺ يقول في دبر الصلاة بعد السلام: لا إله إلا الله فهذا مراده بعد السلام يأتي بالأذكار الشرعية، يقول: أستغفر الله أستغفر الله أستغفر الله يعني: بعد السلام، اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام، ثم يقول: لا إله إلا الله، كما كان النبي يفعل عليه الصلاة والسلام بعد السلام.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16664/المقصود-بدبر-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77617.mp3","categories":["شروح الحديث","التشهد والتسليم"]},{"id":17810,"question":"هذا الأخ السائل أحمد عبد الله مصري مقيم بالرياض يقول سماحة الشيخ: ما كيفية السلام في نهاية الصلاة؟ هل يقول: السلام عليكم ورحمة الله- بسرعة- عن يمينه، السلام عليكم ورحمة الله عن يساره، ويكون بذلك بسرعة؟ أم بانتهاء جملة السلام؟","title":"صفة السلام في نهاية الصلاة","answer":"الجواب: لا. يقول بالهدوء، يسلم بالهدوء: السلام عليكم ورحمة الله، السلام عليكم ورحمة الله، طريقة عادية ليس فيها تكلف، هذه السنة، لا سرعة مفرطة ولا طول مفرط، يكون وسط، السلام عليكم ورحمة الله، السلام عليكم ورحمة الله، أما: السلام عليكم ورحمة الله لا يطول لا، أما العجلة كأنه ملحوق كأنه مطرود، لا. وسط. نعم.","link":"https://binbaz.org.sa/fatwas/16794/صفة-السلام-في-نهاية-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59716.mp3","categories":["التشهد والتسليم"]},{"id":17811,"question":"ما حكم زيادة (ورحمة الله وبركاته)؟","title":"حكم زيادة (ورحمة الله وبركاته) في السلام","answer":"الجواب: الأفضل الاقتصار على (رحمة الله)، هذا هو المحفوظ في الأدلة، السلام عليكم ورحمة الله. نعم.\nالمقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/16797/حكم-زيادة-ورحمة-الله-وبركاته-في-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59717.mp3","categories":["التشهد والتسليم"]},{"id":18237,"question":"زيادة (السلام عليكم ورحمة الله وبركاته) في السلام هل هي واردة يا شيخ؟","title":"حكم زيادة: (وبركاته) في التسليم","answer":"الجواب: وردت، لكن في إسنادها نظر، والأصح: السلام عليكم ورحمة الله، مثلما عليه العمل الآن. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17290/حكم-زيادة-وبركاته-في-التسليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78223.mp3","categories":["التشهد والتسليم"]},{"id":18241,"question":"هذا السائل الفاتح الصديق سوداني، له سؤال يقول فيه سماحة الشيخ: لنا في قريتنا مسجد يصلون فيه صلاة الجماعة، ولكن الإمام بعد الانتهاء من الصلاة يسلم على جهة يده اليمنى فقط، أي تسليمة واحدة هل يجوز ذلك؟","title":"حكم الاكتفاء بتسليمة واحدة عن اليمين","answer":"الجواب: لا، الصواب أنه لا يجوز، يُعلَّم، الذي مضى مضى، لكن يُعلَّم أن يسلم اثنتين، الثابت عن النبي ﷺ أنه كان يسلم تسليمتين، عليه الصلاة والسلام، فيعلم هذا الإمام، وما مضى يغفر الله له إن شاء الله، لجهله أو اعتقاده أن هذا هو المجزي، لكن في المستقبل يجاهد نفسه، ويعلم ويوضح له أن الواجب عليه أن يسلم تسليمتين. نعم.","link":"https://binbaz.org.sa/fatwas/17289/حكم-الاكتفاء-بتسليمة-واحدة-عن-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78222.mp3","categories":["التشهد والتسليم"]},{"id":18519,"question":"أختنا إيمان سلطان سعود من الدمام -وقد نسيت أن أذكر اسمها في مقدمة الرسالة- تسأل سؤالاً آخر وتقول: ما حكم التلويح بالإصبع في الصلاة، أي: في قراءة التحيات؟","title":"حكم الإشارة بالإصبع عند قراءة التحيات","answer":"الجواب: سنة، الإشارة الإصبع في التحيات عند ذكر الله وعند..، فيها جميع التحيات، يكون الشاهد مفتوحًا منصوبًا نصبًا غير كامل، نصبًا فيه انحناء، إشارة إلى التوحيد، فإذا جاء عند ذكر الدعاء مثل: اللهم صل على محمد، اللهم بارك، وبقية الدعاء يحركه قليلًا، كما جاء في بعض الروايات، هذا كله من السنة، الإشارة من السنة، والتحريك عند الدعاء من السنة، لكن يكون التحريك قليل ليس فيه كثرة جمعًا بين الروايات، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17635/حكم-الاشارة-بالاصبع-عند-قراءة-التحيات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_870/nour_87008.mp3","categories":["التشهد والتسليم"]},{"id":18999,"question":"عند الشهادتين نقول: السلام عليك يا أيها النبي ورحمة الله وبركاته، لكني سمعت أناسًا يقولون: يجب أن تقول: السلام على النبي ورحمة الله وبركاته، فأيهما الصحيح؟ أم الاثنتان صحيحتان؟ جزاكم الله خيرًا.","title":"حكم قول: (السلام على النبي) في التشهد","answer":"الجواب: الصواب: أنه يقول: السلام عليك أيها النبي في التشهدين، هكذا جاءت الأحاديث الصحيحة من تعليم النبي ﷺ للأمة، علم الصحابة هكذا. وروي عن بعض الصحابة أنهم كانوا يستعملون النوع الثاني -السلام على النبي- بعد موت النبي ﷺ ولكن هذا جائز، واجتهاد لبعض الصحابة، وليس بلازم. لكن لو فعله الإنسان صح، لكن كونه يأتي بالألفاظ التي علمها النبي ﷺ أمته وهو يعلم أنه سيموت ولم يقل لهم: إذا مت فغيروا، ويعلم أنهم يغيبون عن المدينة، ويقرءون الصلاة في بلاد بعيدة، ولم يقل لهم إذا كنتم بعيدين غائبين أو بعد موتي غيروا. فدل ذلك على أن هذا اللفظ باقٍ، السلام عليك أيها النبي في حياته، وفي حضرته، وفي غيبته، وبعد الموت، هذا هو الصواب، وهذا هو الذي ثبت في الأحاديث الصحيحة عن ابن مسعود وعن غيره رضي الله عن الجميع . نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18164/حكم-قول-السلام-على-النبي-في-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_795/nour_79505.mp3","categories":["التشهد والتسليم"]},{"id":19008,"question":"عند الشهادتين، وعند رفع الأصبع، عندما نقول: أشهد أن لا إله إلا الله وأشهد أن محمدًا رسول الله ﷺ فكل شخص من المصلين يرفع إصبعه على طريقة معينة، فمن يرفعه مرة واحدة، ومن يرفعها مرتين؛ لأنه يقول: إنهما شهادتان، ومن يبقى يحرك إصبعه إلى نهاية الصلاة الإبراهيمية، أرجو أن تتفضلوا بإجابتي على الصحيح؟ أم أن الجميع صحيح؟ جزاكم الله خيرًا.","title":"رفع السبابة وتحريكها في التشهد","answer":"الجواب: السنة رفع الإصبع في التشهد الأول والآخر، من أول التحيات إلى النهاية وإصبعه مرفوعة، يعني السبابة التي تلي الإبهام مرفوعة رفعًا غير كامل، إشارة للتوحيد. هكذا ثبت عن النبي ﷺ: أنه كان يشير بالسبابة في تشهده الأول والأخير عليه الصلاة والسلام من أوله إلى النهاية. أما التحريك فالأفضل أن يحركها عند الدعاء عند قوله: اللهم صل على محمد، وعند قوله: أعوذ بالله من عذاب جهنم، وعند قوله: اللهم اغفر لي، أو اللهم آتنا في الدنيا حسنة، أو اللهم أعني على ذكرك، يحرك عند الدعاء تحريكًا خفيفًا، هذا هو الأفضل، وأما كون الإصبع قائمة فهي قائمة من أول التشهد إلى آخره إشارة للتوحيد. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18165/رفع-السبابة-وتحريكها-في-التشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_795/nour_79506.mp3","categories":["التشهد والتسليم"]},{"id":19094,"question":"الدعاء بعد التشهد في الركعة الثانية وفي الرباعية سهوًا؟","title":"حكم الدعاء بعد التشهد الأول والأخير","answer":"الجواب: الدعاء في التشهد الأول ما هو بمشروع، وإذا أتى به فلا سهو عليه، لا سجود عليه لكن إن سجد فلا بأس؛ لأنه أتى به في غير محله، أما الدعاء في التشهد الأخير فهو مشروع. الدعاء في التشهد الأخير قبل السلام مشروع مأمور به، فينبغي له أن يدعو بالدعوات الطيبة والمأثورة أفضل، الدعاء المأثور يكون أفضل، كالتعوذ بالله من عذاب جهنم ومن عذاب القبر ومن فتنة المحيا والممات ومن فتنة المسيح الدجال، وسؤال المغفرة والعفو، وقول: اللهم أعني على ذكرك وشكرك وحسن عبادتك كل هذا مشروع يعني: في آخر الصلاة قبل أن يسلم، هذا الدعاء مشروع، نعم.","link":"https://binbaz.org.sa/fatwas/18264/حكم-الدعاء-بعد-التشهد-الاول-والاخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_930/nour_93008.mp3","categories":["الأدعية والأذكار","التشهد والتسليم"]},{"id":19226,"question":"من دولة الكويت هذه رسالة بعث بها أحد الإخوة رمز إلى اسمه بالحروف (ع. ع. م) أخونا يقول: أرى من المصلين في المسجد عند الجلوس للتشهد الأخير عند السلام يهز البعض رقابهم إلى أسفل، ثم يسلم على يمينه، ويهزها إلى أسفل، ثم يسلم على يساره، أفيدونا عن هذا هل له حكم ؟الشيخ: أعد أعد.المقدم: يقول: أرى من المصلين في المسجد عند الجلوس للتشهد الأخير عند السلام يهز البعض رقابهم إلى أسفل، ثم يسلم على يمينه، ويهزها إلى أسفل ثم يسلم على يساره، أفيدونا هل لهذا أصل؟ جزاكم الله خيرًا.","title":"حكم هز الرقبة إلى أسفل عند السلام من الصلاة","answer":"الجواب: هذا لا أصل له، السنة الخشوع في الصلاة والطمأنينة، وعدم هز الرقاب أو الأيدي، وبعض الناس يهز يديه ويومئ بيديه حين الجلوس للتحيات قبل أن يسلم، وقد أنكر النبي على من فعل هذا عليه الصلاة والسلام، وأمرهم بالسكون في الصلاة، قال: ما لي أراكم تومئون بأيديكم كأنها أذناب خيل شمس، يعني: عند السلام. فالحاصل أن السنة الركود والخشوع والطمأنينة وعدم الحركة، لا بالرءوس ولا بالأيدي عند السلام ولا قبله ولا في أي جزء من أجزاء الصلاة، الواجب الطمأنينة والبعد عن العبث، قال الله سبحانه: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]، فكونه يعبث برقبته أو يعبث بيديه كل هذا لا أصل له، وأقل أحواله الكراهة الشديدة، وقد يحرم، إذا كثر وتوالى حرم وأبطل الصلاة، إذا توالى العبث وكثر حرم وأبطل الصلاة، نسأل الله السلامة، فالواجب الحذر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18415/حكم-هز-الرقبة-الى-اسفل-عند-السلام-من-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_890/nour_89004.mp3","categories":["التشهد والتسليم"]},{"id":19528,"question":"يقول السائل سماحة الشيخ: عندما يسلم الإمام من الصلاة، هل يسلم المأمومون بعد التسليمة الثانية أو الأولى مباشرة؟","title":"وقت تسليم المأمومون","answer":"الجواب: بعد الثانية، لا يسلمون حتى يسلم الثانية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18772/وقت-تسليم-المامومون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93936.mp3","categories":["التشهد والتسليم"]},{"id":19543,"question":"هل الدعاء مفردًا بعد الصلاة المكتوبة بدعة، أم المقصود بالبدعة هو الدعاء بشكل جماعي في المسجد؟وإذا كان الدعاء بعد الصلاة المكتوبة بدعة فما تفسير الحديث الذي يقول: عن أبي أمامة  قال: «قيل لرسول الله ﷺ: أي الدعاء أسمع؟ قال: جوف الليل الآخر، ودبر الصلوات المكتوبات رواه الترمذي وقال: حديث حسن؟","title":"حكم الدعاء دبر الصلوات المكتوبات","answer":"الجواب: الدعاء في دبر الصلاة مشروع وليس به بأس، والأفضل أن يكون قبل السلام بعدما يصلي على النبي ﷺ وبعدما يتعوذ بالله من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال يتعوذ بما شاء، يقول: اللهم أجرني من كذا، أجرني من شر نفسي، اللهم أعذني من شر نفسي، اللهم أعذني من الشيطان، اللهم اغفر لي ولوالدي، يدعو بما يسر الله له، وإذا كان الدعاء مشروعًا واردًا كان أفضل مثل: اللهم اغفر لي ما قدمت، وما أخرت، وما أسررت، وما أعلنت وما أنت أعلم به مني، أنت المقدم وأنت المؤخر لا إله إلا أنت اللهم أعني على ذكرك وشكرك وحسن عبادتك اللهم إني أعوذ بك من البخل، وأعوذ بك من الجبن، وأعوذ بك أن أرد إلى أرذل العمر وأعوذ بك من فتنة الدنيا وأعوذ بك من عذاب القبر كل هذا وارد عن النبي ﷺ. كذلك اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم أيضًا هذا ثابت عن النبي ﷺ أنه علمه الصديق أن يدعو به في صلاته. فالحاصل أن الدعاء في دبر الصلاة أمر مشروع، وأفضله ما كان قبل السلام، وإن دعا بعد السلام وبعد الذكر بينه وبين نفسه فلا بأس، قد جاء في رواية مسلم من حديث علي  ما يدل على شرعية الدعاء أيضًا بعد السلام: اللهم اغفر لي ما قدمت وما أخرت، وما أسررت وما أعلنت، وما أسرفت وما أنت أعلم به مني، أنت المقدم وأنت المؤخر لا إله إلا أنت، أو قال: أنت إلهي لا إله إلا أنت. فإذا دعا بينه وبين نفسه بعض الدعوات بعد الذكر وبعد السلام فلا حرج في ذلك، لكن يبدأ أولًا حين يسلم في الفريضة أستغفر الله ثلاثًا اللهم أنت السلام، ومنك السلام تباركت يا ذا الجلال والإكرام ثم يذكر الله يقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله ولا نعبد إلا إياه له النعمة وله الفضل وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون، اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد فإذا دعا بعد هذا بما تيسر كله طيب ولا حرج في ذلك والحمد لله، نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18794/حكم-الدعاء-دبر-الصلوات-المكتوبات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_940/nour_94006.mp3","categories":["الأدعية والأذكار","التشهد والتسليم"]},{"id":19572,"question":"السائلة من حائل تقول: ما هي مواضع دفع السبابة في التشهد الأول والأخير، والدعاء قبل السلام وفي أثناء التشهد، هل ينظر المسلم إلى موضع سجوده أم إلى السبابة؟","title":"محل النظر في التشهد ومواضع رفع السبابة فيه","answer":"الجواب: إذا جلس للتشهد الأول والأخير ينظر إلى السبابة إلى سبابته، ويشير بها في التحيات، ويحركها في الدعاء عند الدعاء في التشهد الأخير يحركها قليلًا، ويشير بها إلى توحيد الله، وأن الله واحد لا شريك له، ويدعو في التشهد الأخير. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18840/محل-النظر-في-التشهد-ومواضع-رفع-السبابة-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94724.mp3","categories":["التشهد والتسليم"]},{"id":19650,"question":"سماحة الشيخ، يقول السائل أبو عبد الرحمن: ما رأيكم فيمن يقول في التشهد: اللهم صل وبارك على محمد، أي يجمعهما معًا في الصلاة؟","title":"حكم قول المصلي في التشهد: اللهم صل وبارك على محمد","answer":"الجواب: السنة أن يفرد كل واحد اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد هذه السنة التي جاءت عن النبي ﷺ الصلاة وحدها والبركة وحدها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18934/حكم-قول-المصلي-في-التشهد-اللهم-صل-وبارك-على-محمد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95004.mp3","categories":["التشهد والتسليم"]}]
